DG.put("chandee-charitr-ukti-bilaas/5",{"n":5,"title":null,"title_roman":null,"page":194,"blocks":[{"type":"heading","kind":"chhand","name":"ਸੋਰਠਾ","gurmukhi":"ਸੋਰਠਾ","roman":"Sorthaa","meaning_en":"Sortha.","page":194,"meaning_status":"draft"},{"type":"verse","number":[117],"number_text":"੧੧੭।","page":194,"lines":[{"gurmukhi":"ਘਾਇਲ ਘੂਮਤ ਕੋਟਿ ਜਾਇ ਪੁਕਾਰੇ ਸੁੰਭ ਪੈ।","roman":"Ghaail ghoomat koti jaai pukaare sunbh pai |","meaning_en":"Millions of wounded, reeling, went and cried out to Sumbh:","page":194,"meaning_status":"draft"},{"gurmukhi":"ਮਾਰੇ ਦੇਵੀ ਘੋਟਿ ਸੁਭਟ ਕਟਕ ਕੇ ਬਿਕਟ ਅਤਿ। ੧੧੭।","roman":"Maare devee ghoti subhat katak ke bikat ati | 117 |","meaning_en":"'The goddess has crushed and slain the very formidable warriors of the army.' 117.","page":194,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਦੋਹਰਾ","gurmukhi":"ਦੋਹਰਾ","roman":"Dohraa","meaning_en":"Dohra.","page":194,"meaning_status":"draft"},{"type":"verse","number":[118],"number_text":"੧੧੮।","page":194,"lines":[{"gurmukhi":"ਰਾਜ ਗਾਤ ਕੇ ਬਾਤਿ ਇਹ ਕਹੀ ਜੁ ਤਾਹੀ ਠਉਰ।","roman":"Raaj gaat ke baati ih kahee ju taahee thaur |","meaning_en":"The king, in his own person, said this right there:","page":194,"meaning_status":"draft","note":"ਰਾਜ ਗਾਤ ਕੇ: read as 'the king himself'; uncertain."},{"gurmukhi":"ਮਰਿ ਹੋ ਜੀਅਤਿ ਨ ਛਾਡਿ ਹੋ ਕਹਿਓ ਸਤਿ ਨਹਿ ਅਉਰ। ੧੧੮।","roman":"Mari ho jeeati na chhaadi ho kahio sati nahi aur | 118 |","meaning_en":"'I shall kill her; I will not leave her alive; I speak the truth, nothing else.' 118.","page":194,"meaning_status":"draft"}]},{"type":"verse","number":[119],"number_text":"੧੧੯।","page":194,"lines":[{"gurmukhi":"ਤੁੰਡ ਸੁੰਭ ਕੇ ਚੰਡਿਕਾ ਚਢਿ ਬੋਲੀ ਇਹ ਭਾਇ।","roman":"Tund sunbh ke chandikaa chadhi bolee ih bhaai |","meaning_en":"Chandika came to be on Sumbh's lips in this way,","page":194,"meaning_status":"draft","note":"ਤੁੰਡ ... ਚਢਿ: 'came into his mouth', i.e. he kept speaking of her; uncertain."},{"gurmukhi":"ਮਾਨੋ ਆਪਨੀ ਮ੍ਰਿਤ ਕੋ ਲੀਨੋ ਅਸੁਰ ਬੁਲਾਇ। ੧੧੯।","roman":"Maano aapnee mrit ko leeno asur bulaai | 119 |","meaning_en":"as if the demon had summoned his own death. 119.","page":194,"meaning_status":"draft"}]},{"type":"verse","number":[120],"number_text":"੧੨੦।","page":195,"lines":[{"gurmukhi":"ਸੁੰਭ ਨਿਸੁੰਭ ਸੁ ਦੁਹੁੰ ਮਿਲ ਬੈਠਿ ਮੰਤ੍ਰ ਤਬ ਕੀਨ।","roman":"Sunbh nisunbh su duhun mil baithi mantr tab keen |","meaning_en":"Sumbh and Nisumbh then sat together and took counsel;","page":195,"meaning_status":"draft"},{"gurmukhi":"ਸੈਨਾ ਸਕਲ ਬੁਲਾਇ ਕੈ ਸੁਭਟ ਬੀਰ ਚੁਨ ਲੀਨ। ੧੨੦।","roman":"Sainaa sakal bulaai kai subhat beer chun leen | 120 |","meaning_en":"summoning the whole army, they chose fine heroes. 120.","page":195,"meaning_status":"draft"}]},{"type":"verse","number":[121],"number_text":"੧੨੧।","page":195,"lines":[{"gurmukhi":"ਰਕਤਬੀਜ ਕੋ ਭੇਜੀਏ ਮੰਤ੍ਰਨ ਕਹੀ ਬਿਚਾਰ।","roman":"Rakatbeej ko bhejee'e mantran kahee bichaar |","meaning_en":"'Send Raktabij,' the ministers said after deliberation,","page":195,"meaning_status":"draft"},{"gurmukhi":"ਪਾਥਰ ਜਿਉ ਗਿਰਿ ਡਾਰ ਕੇ ਚੰਡਹਿ ਹਨੈ ਹਕਾਰਿ। ੧੨੧।","roman":"Paathar jiu giri daar ke chandhi hanai hakaari | 121 |","meaning_en":"'he will hurl her down like a stone from the mountain, and kill Chandi with a challenge.' 121.","page":195,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਸੋਰਠਾ","gurmukhi":"ਸੋਰਠਾ","roman":"Sorthaa","meaning_en":"Sortha.","page":195,"meaning_status":"draft"},{"type":"verse","number":[122],"number_text":"੧੨੨।","page":195,"lines":[{"gurmukhi":"ਭੇਜੋ ਕੋਊ ਦੂਤ ਗ੍ਰਹ ਤੇ ਲਿਆਵੈ ਤਾਹਿ ਕੋ।","roman":"Bhejo ko'oo doot grah te liaavai taahi ko |","meaning_en":"'Send some messenger to bring him from his house,","page":195,"meaning_status":"draft"},{"gurmukhi":"ਜੀਤਿਓ ਜਿਨਿ ਪੁਰਹੂਤ ਭੁਜਬਲਿ ਜਾ ਕੇ ਅਮਿਤ ਹੈ। ੧੨੨।","roman":"Jeetio jini purhoot bhujabli jaa ke amit hai | 122 |","meaning_en":"him who conquered Indra, whose strength of arm is boundless.' 122.","page":195,"meaning_status":"draft","note":"ਪੁਰਹੂਤ: Puruhut, a name of Indra."}]},{"type":"heading","kind":"chhand","name":"ਦੋਹਰਾ","gurmukhi":"ਦੋਹਰਾ","roman":"Dohraa","meaning_en":"Dohra.","page":195,"meaning_status":"draft"},{"type":"verse","number":[123],"number_text":"੧੨੩।","page":195,"lines":[{"gurmukhi":"ਸ੍ਰੋਣਤ ਬਿੰਦ ਪੈ ਦੈਤ ਇਕੁ ਗਇਓ ਕਰੀ ਅਰਦਾਸਿ।","roman":"Sronat bind pai dait iku gaio karee ardaasi |","meaning_en":"A demon went to Shronat Bind (Raktabij) and made a request:","page":195,"meaning_status":"draft","note":"ਸ੍ਰੋਣਤ ਬਿੰਦ: 'blood-drop', another name for Raktabij."},{"gurmukhi":"ਰਾਜ ਬੁਲਾਵਤ ਸਭਾ ਮੈ ਬੇਗ ਚਲੋ ਤਿਹ ਪਾਸਿ। ੧੨੩।","roman":"Raaj bulaavat sabhaa mai beg chalo tih paasi | 123 |","meaning_en":"'The king summons you to the court; go to him quickly.' 123.","page":195,"meaning_status":"draft"}]},{"type":"verse","number":[124],"number_text":"੧੨੪।","page":195,"lines":[{"gurmukhi":"ਰਕਤ ਬੀਜ ਨ੍ਰਿਪ ਸੁੰਭ ਕੋ ਕੀਨੋ ਆਨਿ ਪ੍ਰਨਾਮ।","roman":"Rakat beej nrip sunbh ko keeno aani pranaam |","meaning_en":"Raktabij came and bowed to King Sumbh;","page":195,"meaning_status":"draft"},{"gurmukhi":"ਅਸੁਰ ਸਭਾ ਮਧਿ ਭਾਉ ਕਰਿ ਕਹਿਓ ਕਰਹੁ ਮਮ ਕਾਮ। ੧੨੪।","roman":"Asur sabhaa madhi bhaau kari kahio karhu mam kaam | 124 |","meaning_en":"in the demons' court the king, with affection, said, 'Do my task.' 124.","page":195,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਸ੍ਵੈਯਾ","gurmukhi":"ਸ੍ਵੈਯਾ","roman":"Svaiyaa","meaning_en":"Savaiya.","page":195,"meaning_status":"draft"},{"type":"verse","number":[125],"number_text":"੧੨੫।","page":195,"lines":[{"gurmukhi":"ਸ੍ਰਉਣਤ ਬਿੰਦ ਕੋ ਸੁੰਭ ਨਿਸੁੰਭ ਬੁਲਾਇ ਬੈਠਾਇ ਕੈ ਆਦਰੁ ਕੀਨੋ।","roman":"Sraunat bind ko sunbh nisunbh bulaai baithaai kai aadru keeno |","meaning_en":"Sumbh and Nisumbh called Raktabij, seated him, and honoured him;","page":195,"meaning_status":"draft"},{"gurmukhi":"ਦੈ ਸਿਰਤਾਜ ਬਡੇ ਗਜਰਾਜ ਸੁ ਬਾਜ ਦਏ ਰਿਝਵਾਇ ਕੈ ਲੀਨੋ।","roman":"Dai sirtaaj bade gajraaj su baaj dae rijhvaai kai leeno |","meaning_en":"giving him a crown, great elephants and horses, they won him over.","page":195,"meaning_status":"draft"},{"gurmukhi":"ਪਾਨ ਲੈ ਦੈਤ ਕਹੀ ਇਹ ਚੰਡ ਕੋ ਰੁੰਡ ਕਰੋ ਅਬ ਮੁੰਡ ਬਿਹੀਨੋ।","roman":"Paan lai dait kahee ih chand ko rund karo ab mund biheeno |","meaning_en":"Taking the betel, the demon said, 'Now I shall make Chandi's trunk headless.'","page":195,"meaning_status":"draft"},{"gurmukhi":"ਐਸੇ ਕਹਿਓ ਤਿਨ ਮਧਿ ਸਭਾ ਨ੍ਰਿਪ ਰੀਝ ਕੈ ਮੇਘ ਅਡੰਬਰ ਦੀਨੋ। ੧੨੫।","roman":"Aise kahio tin madhi sabhaa nrip reejh kai megh adanbar deeno | 125 |","meaning_en":"When he spoke thus in the court, the king, pleased, gave him a canopy like the clouds. 125.","page":195,"meaning_status":"draft","note":"ਮੇਘ ਅਡੰਬਰ: a grand canopy (meghadambar)."}]},{"type":"verse","number":[126],"number_text":"੧੨੬।","page":195,"lines":[{"gurmukhi":"ਸ੍ਰੋਣਤ ਬਿੰਦ ਕੋ ਸੁੰਭ ਨਿਸੁੰਭ ਕਹਿਓ ਤੁਮ ਜਾਹੁ ਮਹਾ ਦਲੁ ਲੈ ਕੈ।","roman":"Sronat bind ko sunbh nisunbh kahio tum jaahu mahaa dalu lai kai |","meaning_en":"Sumbh and Nisumbh said to Raktabij, 'Go, taking a great army;","page":195,"meaning_status":"draft"},{"gurmukhi":"ਛਾਰ ਕਰੋ ਗਰੂਏ ਗਿਰ ਰਾਜਹਿ ਚੰਡਿ ਪਚਾਰਿ ਹਨੋ ਬਲੁ ਕੈ ਕੈ।","roman":"Chhaar karo garooe gir raajhi chandi pachaari hano balu kai kai |","meaning_en":"reduce the great king of mountains to ashes, challenge Chandi and kill her with all your strength.'","page":195,"meaning_status":"draft"},{"gurmukhi":"ਕਾਨਨ ਮੈ ਨ੍ਰਿਪ ਕੀ ਸੁਨੀ ਬਾਤ ਰਿਸਾਤ ਚਲਿਓ ਚੜਿ ਉਪਰ ਗੈ ਕੈ।","roman":"Kaanan mai nrip kee sunee baat risaat chalio chari upar gai kai |","meaning_en":"Hearing the king's word with his ears, he set out in anger, riding upon an elephant,","page":195,"meaning_status":"draft"},{"gurmukhi":"ਮਾਨੋ ਪ੍ਰਤਛ ਹੋਇ ਅੰਤਿਕ ਦੰਤਿ ਕੋ ਲੈ ਕੈ ਚਲਿਓ ਰਨਿ ਹੇਤ ਜੁ ਛੈ ਕੈ। ੧੨੬।","roman":"Maano pratachh hoi antik danti ko lai kai chalio rani het ju chhai kai | 126 |","meaning_en":"as if Death, made manifest, were riding an elephant to battle to destroy. 126.","page":195,"meaning_status":"draft","note":"ਅੰਤਿਕ: Death; ਦੰਤਿ: an elephant."}]},{"type":"verse","number":[127],"number_text":"੧੨੭।","page":195,"lines":[{"gurmukhi":"ਬੀਜ ਰਕਤ੍ਰ ਸੁ ਬੰਬ ਬਜਾਇ ਕੈ ਆਗੈ ਕੀਏ ਗਜ ਬਾਜ ਰਥਈਆ।","roman":"Beej rakatr su banb bajaai kai aagai kee'e gaj baaj rathaeeaa |","meaning_en":"Raktabij, beating the war drum, put elephants, horses and charioteers in front;","page":195,"meaning_status":"draft"},{"gurmukhi":"ਏਕ ਤੇ ਏਕ ਮਹਾ ਬਲਿ ਦਾਨਵ ਮੇਰ ਕੋ ਪਾਇਨ ਸਾਥ ਮਥਈਆ।","roman":"Ek te ek mahaa bali daanav mer ko paain saath mathaeeaa |","meaning_en":"demons each mightier than the other, who could churn Mount Meru with their feet.","page":195,"meaning_status":"draft"},{"gurmukhi":"ਦੇਖਿ ਤਿਨੇ ਸੁਭ ਅੰਗ ਸੁ ਦੀਰਘ ਕਉਚ ਸਜੇ ਕਟਿ ਬਾਧਿ ਭਥਈਆ।","roman":"Dekhi tine subh ang su deeragh kauch saje kati baadhi bhathaeeaa |","meaning_en":"Behold their fine, tall bodies, adorned with armour, quivers tied at their waists;","page":195,"meaning_status":"draft","note":"ਭਥਈਆ: read as 'quivers'; uncertain."},{"gurmukhi":"ਲੀਨੇ ਕਮਾਨਨ ਬਾਨ ਕ੍ਰਿਪਾਨ ਸਮਾਨ ਕੈ ਸਾਥ ਲਏ ਜੋ ਸਥਈਆ। ੧੨੭।","roman":"Leene kamaanan baan kripaan samaan kai saath lae jo sathaeeaa | 127 |","meaning_en":"they took bows, arrows and swords, and brought their companions with them. 127.","page":195,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਦੋਹਰਾ","gurmukhi":"ਦੋਹਰਾ","roman":"Dohraa","meaning_en":"Dohra.","page":196,"meaning_status":"draft"},{"type":"verse","number":[128],"number_text":"੧੨੮।","page":196,"lines":[{"gurmukhi":"ਰਕਤ ਬੀਜ ਦਲ ਸਾਜ ਕੈ ਉਤਰੇ ਤਟਿ ਗਿਰਿ ਰਾਜ।","roman":"Rakat beej dal saaj kai utre tati giri raaj |","meaning_en":"Raktabij arrayed his army and encamped at the foot of the king of mountains;","page":196,"meaning_status":"draft"},{"gurmukhi":"ਸ੍ਰਵਣਿ ਕੁਲਾਹਲ ਸੁਨਿ ਸਿਵਾ ਕਰਿਓ ਜੁਧ ਕੋ ਸਾਜ। ੧੨੮।","roman":"Sravni kulaahal suni sivaa kario judh ko saaj | 128 |","meaning_en":"hearing the uproar with her ears, Shiva (the goddess) made ready for battle. 128.","page":196,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਸੋਰਠਾ","gurmukhi":"ਸੋਰਠਾ","roman":"Sorthaa","meaning_en":"Sortha.","page":196,"meaning_status":"draft"},{"type":"verse","number":[129],"number_text":"੧੨੯।","page":196,"lines":[{"gurmukhi":"ਹੁਇ ਸਿੰਘਹਿ ਅਸਵਾਰ ਗਾਜ ਗਾਜ ਕੈ ਚੰਡਿਕਾ।","roman":"Hui singhhi asvaar gaaj gaaj kai chandikaa |","meaning_en":"Mounted on the lion, roaring and roaring, Chandika","page":196,"meaning_status":"draft"},{"gurmukhi":"ਚਲੀ ਪ੍ਰਬਲ ਅਸਿ ਧਾਰਿ ਰਕਤਿ ਬੀਜ ਕੇ ਬਧ ਨਮਿਤ। ੧੨੯।","roman":"Chalee prabal asi dhaari rakti beej ke badh namit | 129 |","meaning_en":"set out, the mighty one, holding her sword, to slay Raktabij. 129.","page":196,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਸ੍ਵੈਯਾ","gurmukhi":"ਸ੍ਵੈਯਾ","roman":"Svaiyaa","meaning_en":"Savaiya.","page":196,"meaning_status":"draft"},{"type":"verse","number":[130],"number_text":"੧੩੦।","page":196,"lines":[{"gurmukhi":"ਆਵਤ ਦੇਖ ਕੇ ਚੰਡਿ ਪ੍ਰਚੰਡ ਕੋ ਸ੍ਰੋਣਤਬਿੰਦ ਮਹਾ ਹਰਖਿਓ ਹੈ।","roman":"Aavat dekh ke chandi prachand ko sronatbind mahaa harkhio hai |","meaning_en":"Seeing fierce Chandi coming, Raktabij greatly rejoiced.","page":196,"meaning_status":"draft"},{"gurmukhi":"ਆਗੇ ਹ੍ਵੈ ਸਤ੍ਰੁ ਧਸੈ ਰਨ ਮਧਿ ਸੁ ਕ੍ਰੁਧ ਕੇ ਜੁਧਹਿ ਕੋ ਸਰਖਿਓ ਹੈ।","roman":"Aage hvai satru dhasai ran madhi su krudh ke judhhi ko sarkhio hai |","meaning_en":"The enemy went ahead and plunged into the battle, moving forward in anger to fight.","page":196,"meaning_status":"draft","note":"ਸਰਖਿਓ: read as 'advanced'; uncertain."},{"gurmukhi":"ਲੈ ਉਮਡਿਓ ਦਲੁ ਬਾਦਲੁ ਸੋ ਕਵਿ ਨੈ ਜਸੁ ਇਆ ਛਬਿ ਕੋ ਪਰਖਿਓ ਹੈ।","roman":"Lai umdio dalu baadlu so kavi nai jasu iaa chhabi ko parkhio hai |","meaning_en":"He surged forward with his army like a cloud; the poet perceived the glory of this sight:","page":196,"meaning_status":"draft"},{"gurmukhi":"ਤੀਰ ਚਲੈ ਇਮ ਬੀਰਨ ਕੇ ਬਹੁ ਮੇਘ ਮਨੋ ਬਲੁ ਕੈ ਬਰਖਿਓ ਹੈ।੧੩੦।","roman":"Teer chalai im beeran ke bahu megh mano balu kai barkhio hai | 130 |","meaning_en":"the warriors' arrows fly as if clouds were raining down with force. 130.","page":196,"meaning_status":"draft"}]},{"type":"verse","number":[131],"number_text":"੧੩੧।","page":196,"lines":[{"gurmukhi":"ਬੀਰਨ ਕੇ ਕਰ ਤੇ ਛੁਟਿ ਤੀਰ ਸਰੀਰਨ ਚੀਰ ਕੇ ਪਾਰਿ ਪਰਾਨੇ।","roman":"Beeran ke kar te chhuti teer sareeran cheer ke paari paraane |","meaning_en":"The arrows loosed from the warriors' hands pierced bodies and passed out the other side;","page":196,"meaning_status":"draft"},{"gurmukhi":"ਤੋਰ ਸਰਾਸਨ ਫੋਰ ਕੈ ਕਉਚਨ ਮੀਨਨ ਕੇ ਰਿਪੁ ਜਿਉ ਥਹਰਾਨੇ।","roman":"Tor saraasan phor kai kauchan meenan ke ripu jiu thahraane |","meaning_en":"breaking bows and piercing armour, they quivered like kingfishers.","page":196,"meaning_status":"draft","note":"ਮੀਨਨ ਕੇ ਰਿਪੁ: 'enemy of fish', i.e. kingfisher; uncertain."},{"gurmukhi":"ਘਾਉ ਲਗੇ ਤਨ ਚੰਡਿ ਅਨੇਕ ਸੁ ਸ੍ਰਉਣ ਚਲਿਓ ਬਹਿ ਕੈ ਸਰਤਾਨੇ।","roman":"Ghaau lage tan chandi anek su sraun chalio bahi kai sartaane |","meaning_en":"Many wounds struck Chandi's body, and blood flowed like rivers,","page":196,"meaning_status":"draft"},{"gurmukhi":"ਮਾਨਹੁ ਫਾਰਿ ਪਹਾਰ ਹੂੰ ਕੋ ਸੁਤ ਤਛਕ ਕੇ ਨਿਕਸੇ ਕਰ ਬਾਨੇ। ੧੩੧।","roman":"Maanhu phaari pahaar hoon ko sut tachhak ke nikse kar baane | 131 |","meaning_en":"as if the sons of Takshak had burst out of a mountain holding arrows. 131.","page":196,"meaning_status":"draft","note":"Takshak: a king of serpents; image of arrows like snakes; uncertain."}]},{"type":"verse","number":[132],"number_text":"੧੩੨।","page":196,"lines":[{"gurmukhi":"ਬੀਰਨ ਕੇ ਕਰ ਤੇ ਛੁਟਿ ਤੀਰ ਸੁ ਚੰਡਿਕਾ ਸਿੰਘਨ ਜਿਉ ਭਭਕਾਰੀ।","roman":"Beeran ke kar te chhuti teer su chandikaa singhan jiu bhabhkaaree |","meaning_en":"When arrows flew from the warriors' hands, Chandika roared like a lioness;","page":196,"meaning_status":"draft"},{"gurmukhi":"ਲੈ ਕਰਿ ਬਾਨ ਕਮਾਨ ਕ੍ਰਿਪਾਨ ਗਦਾ ਗਹਿ ਚਕ੍ਰ ਛੁਰੀ ਅਉ ਕਟਾਰੀ।","roman":"Lai kari baan kamaan kripaan gadaa gahi chakr chhuree au kataaree |","meaning_en":"taking in her hands bow and arrows, sword, mace, discus, knife and dagger,","page":196,"meaning_status":"draft"},{"gurmukhi":"ਕਾਟ ਕੈ ਦਾਮਨ ਛੇਦ ਕੈ ਭੇਦ ਕੈ ਸਿੰਧੁਰ ਕੀ ਕਰੀ ਭਿੰਨ ਅੰਬਾਰੀ।","roman":"Kaat kai daaman chhed kai bhed kai sindhur kee karee bhinn anbaaree |","meaning_en":"cutting the girths, piercing and tearing, she shattered the howdahs of the elephants,","page":196,"meaning_status":"draft","note":"ਦਾਮਨ: read as girths/ropes; uncertain."},{"gurmukhi":"ਮਾਨਹੁ ਆਗ ਲਗਾਇ ਹਨੂ ਗੜ ਲੰਕ ਅਵਾਸ ਕੀ ਡਾਰੀ ਅਟਾਰੀ। ੧੩੨।","roman":"Maanhu aag lagaai hanoo gar lank avaas kee daaree ataaree | 132 |","meaning_en":"as if Hanuman had set fire to the fort of Lanka and thrown down the upper rooms of its palaces. 132.","page":196,"meaning_status":"draft"}]},{"type":"verse","number":[133],"number_text":"੧੩੩।","page":196,"lines":[{"gurmukhi":"ਤੋਰ ਕੈ ਮੋਰ ਕੈ ਦੈਤਨ ਕੇ ਮੁਖ ਘੋਰ ਕੇ ਚੰਡਿ ਮਹਾ ਅਸਿ ਲੀਨੋ।","roman":"Tor kai mor kai daitan ke mukh ghor ke chandi mahaa asi leeno |","meaning_en":"Breaking and turning back the demons' faces, Chandi took up her great, terrible sword;","page":196,"meaning_status":"draft"},{"gurmukhi":"ਜੋਰ ਕੈ ਕੋਰ ਕੈ ਠੋਰ ਕੈ ਬੀਰ ਸੁ ਰਾਛਸ ਕੋ ਹਤਿ ਕੈ ਤਿਹ ਦੀਨੋ।","roman":"Jor kai kor kai thor kai beer su raachhas ko hati kai tih deeno |","meaning_en":"with force she cut and struck down the warriors, slaying the demons.","page":196,"meaning_status":"draft","note":"ਜੋਰ ਕੈ ਕੋਰ ਕੈ ਠੋਰ ਕੈ: rhyming verbs; sense approximate."},{"gurmukhi":"ਖੋਰ ਕੈ ਤੋਰ ਕੈ ਬੋਰ ਕੈ ਦਾਨਵ ਲੈ ਤਿਨ ਕੇ ਕਰੇ ਹਾਡ ਚਬੀਨੋ।","roman":"Khor kai tor kai bor kai daanav lai tin ke kare haad chabeeno |","meaning_en":"Digging, breaking and drowning the demons, she seized them and chewed their bones;","page":196,"meaning_status":"draft","note":"ਬੋਰ ਕੈ: 'drowning/dipping'; uncertain."},{"gurmukhi":"ਸ੍ਰਉਣ ਕੋ ਪਾਨ ਕਰਿਓ ਜਿਉ ਦਵਾ ਹਰਿ ਸਾਗਰ ਕੋ ਜਲ ਜਿਉ ਰਿਖਿ ਪੀਨੋ। ੧੩੩।","roman":"Sraun ko paan kario jiu davaa hari saagar ko jal jiu rikhi peeno | 133 |","meaning_en":"she drank their blood as a forest fire, or as the sage drank the water of the ocean. 133.","page":196,"meaning_status":"draft","note":"The sage: Agastya, who drank the ocean. ਦਵਾ ਹਰਿ: read as 'forest fire'; uncertain."}]},{"type":"verse","number":[134],"number_text":"੧੩੪।","page":196,"lines":[{"gurmukhi":"ਚੰਡਿ ਪ੍ਰਚੰਡ ਕੁਵੰਡ ਕਰੰ ਗਹਿ ਜੁਧ ਕਰਿਓ ਨ ਗਨੇ ਭਟ ਆਨੇ।","roman":"Chandi prachand kuvand karan gahi judh kario na gane bhat aane |","meaning_en":"Fierce Chandi, holding her bow in hand, fought, heedless of the warriors who came;","page":196,"meaning_status":"draft","note":"ਨ ਗਨੇ ਭਟ ਆਨੇ: 'not counting the warriors who came'."},{"gurmukhi":"ਮਾਰਿ ਦਈ ਸਭ ਦੈਤ ਚਮੂੰ ਤਿਹ ਸ੍ਰਉਣਤ ਜੰਬੁਕ ਗ੍ਰਿਝ ਅਘਾਨੇ।","roman":"Maari daee sabh dait chamoon tih sraunat janbuk grijh aghaane |","meaning_en":"she slew the whole demon army; jackals and vultures were sated with their blood.","page":196,"meaning_status":"draft"},{"gurmukhi":"ਭਾਲ ਭਇਆਨਕ ਦੇਖਿ ਭਵਾਨੀ ਕੋ ਦਾਨਵ ਇਉ ਰਨ ਛਾਡਿ ਪਰਾਨੇ।","roman":"Bhaal bhaiaanak dekhi bhavaanee ko daanav iu ran chhaadi paraane |","meaning_en":"Seeing Bhavani's fearsome forehead, the demons fled the field thus,","page":196,"meaning_status":"draft"},{"gurmukhi":"ਪਉਨ ਕੇ ਗਉਨ ਕੇ ਤੇਜ ਪ੍ਰਤਾਪ ਤੇ ਪੀਪਰ ਕੇ ਜਿਉ ਪਾਤ ਉਡਾਨੇ। ੧੩੪।","roman":"Paun ke gaun ke tej prataap te peepar ke jiu paat udaane | 134 |","meaning_en":"as the leaves of the pipal fly away before the force of the moving wind. 134.","page":196,"meaning_status":"draft"}]},{"type":"verse","number":[135],"number_text":"੧੩੫।","page":197,"lines":[{"gurmukhi":"ਆਹਵ ਮੈ ਖਿਝ ਕੈ ਬਰ ਚੰਡ ਕਰੰ ਧਰ ਕੈ ਹਰਿ ਪੈ ਅਰਿ ਮਾਰੇ।","roman":"Aahav mai khijh kai bar chand karan dhar kai hari pai ari maare |","meaning_en":"Enraged in the battle, the mighty Chandi, sword in hand, on the lion, slew the enemies;","page":197,"meaning_status":"draft","note":"ਕਰੰ ਧਰ ਕੈ: 'holding in hand'; ਹਰਿ ਪੈ: 'on the lion'."},{"gurmukhi":"ਏਕਨ ਤੀਰਨ ਚਕ੍ਰ ਗਦਾ ਹਤਿ ਏਕਨ ਕੇ ਤਨ ਕੇਹਰਿ ਫਾਰੇ।","roman":"Ekan teeran chakr gadaa hati ekan ke tan kehri phaare |","meaning_en":"some she struck with arrows, discus and mace; the bodies of some the lion tore apart.","page":197,"meaning_status":"draft"},{"gurmukhi":"ਹੈ ਦਲ ਗੈ ਦਲ ਪੈਦਲ ਘਾਇ ਕੈ ਮਾਰ ਰਥੀ ਬਿਰਥੀ ਕਰ ਡਾਰੇ।","roman":"Hai dal gai dal paidal ghaai kai maar rathee birthee kar daare |","meaning_en":"Wounding horse-troops, elephant-troops and foot soldiers, she slew charioteers and left them chariotless.","page":197,"meaning_status":"draft"},{"gurmukhi":"ਸਿੰਧੁਰ ਐਸੇ ਪਰੇ ਤਿਹ ਠਉਰ ਜਿਉ ਭੂਮ ਮੈ ਝੂਮਿ ਗਿਰੇ ਗਿਰ ਭਾਰੇ। ੧੩੫।","roman":"Sindhur aise pare tih thaur jiu bhoom mai jhoomi gire gir bhaare | 135 |","meaning_en":"Elephants lay at that place like heavy mountains swaying and falling to the ground. 135.","page":197,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਦੋਹਰਾ","gurmukhi":"ਦੋਹਰਾ","roman":"Dohraa","meaning_en":"Dohra.","page":197,"meaning_status":"draft"},{"type":"verse","number":[136],"number_text":"੧੩੬।","page":197,"lines":[{"gurmukhi":"ਰਕਤ ਬੀਜ ਕੀ ਚਮੂੰ ਸਭ ਭਾਗੀ ਕਰਿ ਤਿਹ ਤ੍ਰਾਸ।","roman":"Rakat beej kee chamoon sabh bhaagee kari tih traas |","meaning_en":"All Raktabij's army fled in terror of her;","page":197,"meaning_status":"draft"},{"gurmukhi":"ਕਹਿਓ ਦੈਤ ਪੁਨਿ ਘੇਰ ਕੈ ਕਰੋ ਚੰਡਿ ਕੋ ਨਾਸ। ੧੩੬।","roman":"Kahio dait puni gher kai karo chandi ko naas | 136 |","meaning_en":"the demon said, 'Surround her again and destroy Chandi.' 136.","page":197,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਸ੍ਵੈਯਾ","gurmukhi":"ਸ੍ਵੈਯਾ","roman":"Svaiyaa","meaning_en":"Savaiya.","page":197,"meaning_status":"draft"},{"type":"verse","number":[137],"number_text":"੧੩੭।","page":197,"lines":[{"gurmukhi":"ਕਾਨਨ ਮੈ ਸੁਨਿ ਕੈ ਇਹ ਬਾਤ ਸੁ ਬੀਰ ਫਿਰੇ ਕਰ ਮੈ ਅਸਿ ਲੈ ਲੈ।","roman":"Kaanan mai suni kai ih baat su beer phire kar mai asi lai lai |","meaning_en":"Hearing this with their ears, the warriors turned back, swords in hand,","page":197,"meaning_status":"draft"},{"gurmukhi":"ਚੰਡਿ ਪ੍ਰਚੰਡ ਸੋ ਜੁਧੁ ਕਰਿਓ ਬਲਿ ਕੈ ਅਤ ਹੀ ਮਨ ਕ੍ਰੁਧਤ ਹ੍ਵੈ ਕੈ।","roman":"Chandi prachand so judhu kario bali kai at hee man krudhat hvai kai |","meaning_en":"and fought fierce Chandi with all their strength, very angry in mind.","page":197,"meaning_status":"draft"},{"gurmukhi":"ਘਾਉ ਲਗੈ ਤਿਨ ਕੇ ਤਨ ਮੈ ਇਮ ਸ੍ਰਉਣ ਗਿਰਿਓ ਧਰਨੀ ਪਰੁ ਚੁਐ ਕੈ।","roman":"Ghaau lagai tin ke tan mai im sraun girio dharnee paru chuai kai |","meaning_en":"Wounds struck their bodies so that blood dripped and fell on the earth;","page":197,"meaning_status":"draft"},{"gurmukhi":"ਆਗ ਲਗੇ ਜਿਮੁ ਕਾਨਨ ਮੈ ਤਨ ਤਿਉ ਰਹੀ ਬਾਨਨ ਕੀ ਧੁਨਿ ਹ੍ਵੈ ਕੈ। ੧੩੭।","roman":"Aag lage jimu kaanan mai tan tiu rahee baanan kee dhuni hvai kai | 137 |","meaning_en":"as when fire breaks out in a forest, so the sound of arrows filled the bodies. 137.","page":197,"meaning_status":"draft","note":"Sense: arrows crackled like a forest fire; uncertain."}]},{"type":"verse","number":[138],"number_text":"੧੩੮।","page":197,"lines":[{"gurmukhi":"ਆਇਸ ਪਾਇ ਕੈ ਦਾਨਵ ਕੋ ਦਲ ਚੰਡਿ ਕੇ ਸਾਮੁਹੇ ਆਇ ਅਰਿਓ ਹੈ।","roman":"Aais paai kai daanav ko dal chandi ke saamuhe aai ario hai |","meaning_en":"Receiving the order, the demon army came and stood firm before Chandi;","page":197,"meaning_status":"draft"},{"gurmukhi":"ਢਾਰ ਅਉ ਸਾਂਗ ਕ੍ਰਿਪਾਨਨਿ ਲੈ ਕਰ ਮੈ ਬਰ ਬੀਰਨ ਜੁਧ ਕਰਿਓ ਹੈ।","roman":"Dhaar au saang kripaanni lai kar mai bar beeran judh kario hai |","meaning_en":"taking shields, lances and swords in hand, the fine warriors fought.","page":197,"meaning_status":"draft"},{"gurmukhi":"ਫੇਰ ਫਿਰੇ ਨਹਿ ਆਹਵ ਤੇ ਮਨ ਮਹਿ ਤਿਹ ਧੀਰਜ ਗਾਢੋ ਧਰਿਓ ਹੈ।","roman":"Pher phire nahi aahav te man mahi tih dheeraj gaadho dhario hai |","meaning_en":"They did not turn back from the battle; they held firm courage in their minds.","page":197,"meaning_status":"draft"},{"gurmukhi":"ਰੋਕ ਲਈ ਚਹੂੰ ਓਰ ਤੇ ਚੰਡਿ ਸੁ ਭਾਨ ਮਨੋ ਪਰਬੇਖ ਪਰਿਓ ਹੈ। ੧੩੮।","roman":"Rok laee chahoon or te chandi su bhaan mano parbekh pario hai | 138 |","meaning_en":"They hemmed in Chandi from all four sides, like a halo forming around the sun. 138.","page":197,"meaning_status":"draft"}]},{"type":"verse","number":[139],"number_text":"੧੩੯।","page":197,"lines":[{"gurmukhi":"ਕੋਪ ਕੈ ਚੰਡਿ ਪ੍ਰਚੰਡ ਕੁਵੰਡ ਮਹਾ ਬਲ ਕੈ ਬਲਵੰਡ ਸੰਭਾਰਿਓ।","roman":"Kop kai chandi prachand kuvand mahaa bal kai balvand sanbhaario |","meaning_en":"In anger, fierce Chandi, with great might, took up her powerful bow;","page":197,"meaning_status":"draft"},{"gurmukhi":"ਦਾਮਿਨਿ ਜਿਉ ਘਨ ਸੇ ਦਲ ਪੈਠਿਕੈ ਕੈ ਪੁਰਜੇ ਪੁਰਜੇ ਦਲੁ ਮਾਰਿਓ।","roman":"Daamini jiu ghan se dal paithikai kai purje purje dalu maario |","meaning_en":"entering the cloud-like army like lightning, she cut the army to pieces.","page":197,"meaning_status":"draft"},{"gurmukhi":"ਬਾਨਨਿ ਸਾਥ ਬਿਦਾਰ ਦਏ ਅਰਿ ਤਾ ਛਬਿ ਕੋ ਕਵਿ ਭਾਉ ਬਿਚਾਰਿਓ।","roman":"Baanni saath bidaar dae ari taa chhabi ko kavi bhaau bichaario |","meaning_en":"With arrows she tore the enemies apart; the poet considered the sense of this sight:","page":197,"meaning_status":"draft"},{"gurmukhi":"ਸੂਰਜ ਕੀ ਕਿਰਨੇ ਸਰਮਾਸਹਿ ਰੇਨ ਅਨੇਕ ਤਹਾ ਕਰਿ ਡਾਰਿਓ। ੧੩੯।","roman":"Sooraj kee kirne sarmaashi ren anek tahaa kari daario | 139 |","meaning_en":"as the sun's rays scatter the darkness, so she made many of them like dust there. 139.","page":197,"meaning_status":"draft","note":"ਸਰਮਾਸਹਿ ਰੇਨ: obscure; perhaps 'dust-motes in the sun's rays'; uncertain."}]},{"type":"verse","number":[140],"number_text":"੧੪੦।","page":197,"lines":[{"gurmukhi":"ਚੰਡਿ ਚਮੂੰ ਬਹੁ ਦੈਤਨ ਕੀ ਹਤਿ ਫੇਰਿ ਪ੍ਰਚੰਡ ਕੁਵੰਡ ਸੰਭਾਰਿਓ।","roman":"Chandi chamoon bahu daitan kee hati pheri prachand kuvand sanbhaario |","meaning_en":"Having slain much of the demon army, Chandi again took up her fierce bow;","page":197,"meaning_status":"draft"},{"gurmukhi":"ਬਾਨਨ ਸੋ ਦਲ ਫੋਰ ਦਇਓ ਬਲ ਕੈ ਬਰ ਸਿੰਘ ਮਹਾ ਭਭਕਾਰਿਓ।","roman":"Baanan so dal phor daio bal kai bar singh mahaa bhabhkaario |","meaning_en":"with arrows she broke the army; the mighty lion roared greatly.","page":197,"meaning_status":"draft"},{"gurmukhi":"ਮਾਰ ਦਏ ਸਿਰਦਾਰ ਬਡੇ ਧਰਿ ਸ੍ਰਉਣ ਬਹਾਇ ਬਡੋ ਰਨ ਪਾਰਿਓ।","roman":"Maar dae sirdaar bade dhari sraun bahaai bado ran paario |","meaning_en":"She slew great chiefs, made blood flow on the earth, and fought a great battle.","page":197,"meaning_status":"draft"},{"gurmukhi":"ਏਕ ਕੇ ਸੀਸ ਦਇਓ ਧਨੁ ਯੌ ਜਨੁ ਕੋਪ ਕੈ ਗਾਜ ਨੇ ਮੰਡਪ ਮਾਰਿਓ। ੧੪੦।","roman":"Ek ke sees daio dhanu yau janu kop kai gaaj ne mandap maario | 140 |","meaning_en":"She struck one on the head with her bow, as if lightning in wrath had struck a pavilion. 140.","page":197,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਦੋਹਰਾ","gurmukhi":"ਦੋਹਰਾ","roman":"Dohraa","meaning_en":"Dohra.","page":197,"meaning_status":"draft"},{"type":"verse","number":[141],"number_text":"੧੪੧।","page":197,"lines":[{"gurmukhi":"ਚੰਡਿ ਚਮੂੰ ਸਭ ਦੈਤ ਕੀ ਐਸੇ ਦਈ ਸੰਘਾਰਿ।","roman":"Chandi chamoon sabh dait kee aise daee sanghaari |","meaning_en":"Chandi destroyed the whole demon army in this way,","page":197,"meaning_status":"draft"},{"gurmukhi":"ਪਉਨ ਪੂਤ ਜਿਉ ਲੰਕ ਕੋ ਡਾਰਿਓ ਬਾਗ ਉਖਾਰਿ। ੧੪੧।","roman":"Paun poot jiu lank ko daario baag ukhaari | 141 |","meaning_en":"as the son of the wind (Hanuman) uprooted the garden of Lanka. 141.","page":197,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਸ੍ਵੈਯਾ","gurmukhi":"ਸ੍ਵੈਯਾ","roman":"Svaiyaa","meaning_en":"Savaiya.","page":198,"meaning_status":"draft"},{"type":"verse","number":[142],"number_text":"੧੪੨।","page":198,"lines":[{"gurmukhi":"ਗਾਜ ਕੈ ਚੰਡਿ ਮਹਾਬਲਿ ਮੇਘ ਸੀ ਬੂੰਦਨ ਜਿਉ ਅਰਿ ਪੈ ਸਰ ਡਾਰੇ।","roman":"Gaaj kai chandi mahaabli megh see boondan jiu ari pai sar daare |","meaning_en":"Roaring like a cloud, the mighty Chandi rained arrows on the enemy like drops;","page":198,"meaning_status":"draft"},{"gurmukhi":"ਦਾਮਿਨਿ ਸੋ ਖਗ ਲੈ ਕਰਿ ਮੈ ਬਹੁ ਬੀਰ ਅਧੰ ਧਰ ਕੈ ਧਰਿ ਮਾਰੇ।","roman":"Daamini so khag lai kari mai bahu beer adhan dhar kai dhari maare |","meaning_en":"taking the lightning-like sword in her hand, she cut many warriors in half and threw them to the ground.","page":198,"meaning_status":"draft","note":"ਅਧੰ ਧਰ: 'half the body'."},{"gurmukhi":"ਘਾਇਲ ਘੂਮ ਪਰੇ ਤਿਹ ਇਉ ਉਪਮਾ ਮਨ ਮੈ ਕਵਿ ਯੌ ਅਨੁਸਾਰੇ।","roman":"Ghaail ghoom pare tih iu upmaa man mai kavi yau anusaare |","meaning_en":"The wounded lay reeling there; the poet conceived this simile in his mind:","page":198,"meaning_status":"draft"},{"gurmukhi":"ਸ੍ਰਉਨ ਪ੍ਰਵਾਹ ਮਨੋ ਸਰਤਾ ਤਿਹ ਮਧਿ ਧਸੀ ਕਰਿ ਲੋਥ ਕਰਾਰੇ। ੧੪੨।","roman":"Sraun pravaah mano sartaa tih madhi dhasee kari loth karaare | 142 |","meaning_en":"the stream of blood is like a river, and the corpses fallen in it are its banks. 142.","page":198,"meaning_status":"draft"}]},{"type":"verse","number":[143],"number_text":"੧੪੩।","page":198,"lines":[{"gurmukhi":"ਐਸੇ ਪਰੇ ਧਰਨੀ ਪਰ ਬੀਰ ਸੁ ਕੈ ਕੈ ਦੁਖੰਡ ਜੁ ਚੰਡਿਹਿ ਡਾਰੇ।","roman":"Aise pare dharnee par beer su kai kai dukhand ju chandihi daare |","meaning_en":"The warriors whom Chandi cut in two lay on the ground thus:","page":198,"meaning_status":"draft"},{"gurmukhi":"ਲੋਥਨ ਉਪਰ ਲੋਥ ਗਿਰੀ ਬਹਿ ਸ੍ਰਉਣ ਚਲਿਓ ਜਨੁ ਕੋਟ ਪਨਾਰੇ।","roman":"Lothan upar loth giree bahi sraun chalio janu kot panaare |","meaning_en":"corpse fell upon corpse, and blood flowed as if from millions of drain-spouts.","page":198,"meaning_status":"draft"},{"gurmukhi":"ਲੈ ਕਰਿ ਬਿਯਾਲ ਸੋ ਬਿਯਾਲ ਬਜਾਵਤ ਸੋ ਉਪਮਾ ਕਵਿ ਯੌ ਮਨਿ ਧਾਰੇ।","roman":"Lai kari biyaal so biyaal bajaavat so upmaa kavi yau mani dhaare |","meaning_en":"Taking elephant and striking elephant against elephant, the poet held this image in mind:","page":198,"meaning_status":"draft","note":"ਬਿਯਾਲ: 'serpent' or 'elephant'; read as elephants dashed together; uncertain."},{"gurmukhi":"ਮਾਨੋ ਮਹਾ ਪ੍ਰਲਏ ਬਹੇ ਪਉਨ ਸੋ ਆਪਸਿ ਮੈ ਭਿਰ ਹੈ ਗਿਰਿ ਭਾਰੇ। ੧੪੩।","roman":"Maano mahaa pralae bahe paun so aapsi mai bhir hai giri bhaare | 143 |","meaning_en":"as if in the great dissolution heavy mountains, driven by the wind, collide with each other. 143.","page":198,"meaning_status":"draft"}]},{"type":"verse","number":[144],"number_text":"੧੪੪।","page":198,"lines":[{"gurmukhi":"ਲੈ ਕਰ ਮੈ ਅਸਿ ਦਾਰੁਨ ਕਾਮ ਕਰੇ ਰਨ ਮੈ ਅਰਿ ਸੋ ਅਰਿਣੀ ਹੈ।","roman":"Lai kar mai asi daarun kaam kare ran mai ari so arinee hai |","meaning_en":"With sword in hand she did dreadful deeds; in battle she stood firm against the enemy.","page":198,"meaning_status":"draft","note":"ਅਰਿਣੀ: read as 'stood fast'; uncertain."},{"gurmukhi":"ਸੂਰ ਹਨੇ ਬਲਿ ਕੈ ਬਲੁਵਾਨ ਸੁ ਸ੍ਰਉਨ ਚਲਿਓ ਬਹਿ ਬੈਤਰਨੀ ਹੈ।","roman":"Soor hane bali kai baluvaan su sraun chalio bahi baitarnee hai |","meaning_en":"With her strength she slew the mighty warriors, and the blood flowed like the Vaitarni.","page":198,"meaning_status":"draft","note":"Vaitarni: the river of the underworld."},{"gurmukhi":"ਬਾਹ ਕਟੀ ਅਧ ਬੀਚ ਤੇ ਸੁੰਡ ਸੀ ਸੋ ਉਪਮਾ ਕਵਿ ਨੇ ਬਰਨੀ ਹੈ।","roman":"Baah katee adh beech te sund see so upmaa kavi ne barnee hai |","meaning_en":"An arm cut off in the middle looked like an elephant's trunk; the poet described it thus:","page":198,"meaning_status":"draft"},{"gurmukhi":"ਆਪਸਿ ਮੈ ਲਰ ਕੈ ਸੁ ਮਨੋ ਗਿਰਿ ਤੇ ਗਿਰੀ ਸਰਪ ਕੀ ਦੁਇ ਘਰਨੀ ਹੈ। ੧੪੪।","roman":"Aapsi mai lar kai su mano giri te giree sarap kee dui gharnee hai | 144 |","meaning_en":"as if two female serpents, fighting each other, had fallen from a mountain. 144.","page":198,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਦੋਹਰਾ","gurmukhi":"ਦੋਹਰਾ","roman":"Dohraa","meaning_en":"Dohra.","page":198,"meaning_status":"draft"},{"type":"verse","number":[145],"number_text":"੧੪੫।","page":198,"lines":[{"gurmukhi":"ਸਕਲ ਪ੍ਰਬਤ ਦਲ ਦੈਤ ਕੋ ਚੰਡੀ ਦਇਓ ਭਜਾਇ।","roman":"Sakal prabat dal dait ko chandee daio bhajaai |","meaning_en":"Chandi put to flight the whole mountain-like demon army,","page":198,"meaning_status":"draft"},{"gurmukhi":"ਪਾਪ ਤਾਪ ਹਰਿ ਜਾਪ ਤੇ ਜੈਸੇ ਜਾਤ ਪਰਾਇ। ੧੪੫।","roman":"Paap taap hari jaap te jaise jaat paraai | 145 |","meaning_en":"as sins and afflictions run away through repeating the Lord's name. 145.","page":198,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਸ੍ਵੈਯਾ","gurmukhi":"ਸ੍ਵੈਯਾ","roman":"Svaiyaa","meaning_en":"Savaiya.","page":198,"meaning_status":"draft"},{"type":"verse","number":[146],"number_text":"੧੪੬।","page":198,"lines":[{"gurmukhi":"ਭਾਨੁ ਤੇ ਜਿਉ ਤਮ ਪਉਨ ਤੇ ਜਿਉ ਘਨੁ ਮੋਰ ਤੇ ਜਿਉ ਫਨਿ ਤਿਉ ਸੁਕਚਾਨੇ।","roman":"Bhaanu te jiu tam paun te jiu ghanu mor te jiu phani tiu sukchaane |","meaning_en":"As darkness before the sun, as clouds before the wind, as snakes before the peacock, so they shrank back;","page":198,"meaning_status":"draft"},{"gurmukhi":"ਸੂਰ ਤੇ ਕਾਤੁਰੁ ਕੂਰ ਤੇ ਚਾਤੁਰੁ ਸਿੰਘ ਤੇ ਸਾਤੁਰ ਏਣਿ ਡਰਾਨੇ।","roman":"Soor te kaaturu koor te chaaturu singh te saatur eni daraane |","meaning_en":"as a coward before a hero, a clever man before a liar, the deer before the lion, so they were afraid;","page":198,"meaning_status":"draft","note":"ਕੂਰ ਤੇ ਚਾਤੁਰੁ: order may be reversed ('the false before the wise'); ਸਾਤੁਰ: unclear."},{"gurmukhi":"ਸੂਮ ਤੇ ਜਿਉ ਜਸੁ ਬਿਓਗ ਤੇ ਜਿਉ ਰਸੁ ਪੂਤ ਕਪੂਤ ਤੇ ਜਿਉ ਬੰਸੁ ਹਾਨੇ।","roman":"Soom te jiu jasu biog te jiu rasu poot kapoot te jiu bansu haane |","meaning_en":"as fame before a miser, as joy before separation, as a family is ruined by an unworthy son;","page":198,"meaning_status":"draft"},{"gurmukhi":"ਧਰਮ ਜਿਉ ਕ੍ਰੁਧ ਤੇ ਭਰਮ ਸੁਬੁਧ ਤੇ ਚੰਡ ਕੇ ਜੁਧ ਤੇ ਦੈਤ ਪਰਾਨੇ। ੧੪੬।","roman":"Dharam jiu krudh te bharam subudh te chand ke judh te dait paraane | 146 |","meaning_en":"as righteousness before anger, as delusion before good understanding, so the demons fled from Chandi's battle. 146.","page":198,"meaning_status":"draft"}]},{"type":"verse","number":[147],"number_text":"੧੪੭।","page":198,"lines":[{"gurmukhi":"ਫੇਰ ਫਿਰੈ ਸਭ ਜੁਧ ਕੇ ਕਾਰਨ ਲੈ ਕਰਵਾਨ ਕ੍ਰੁਧ ਹੁਇ ਧਾਏ।","roman":"Pher phirai sabh judh ke kaaran lai karvaan krudh hui dhaae |","meaning_en":"They all turned back for battle and, taking swords, rushed forward in anger;","page":198,"flags":[{"code":"0x71","reason":"subjoined letter typed after the vowel/nasal sign; put in Unicode order (same printed shape)"}],"meaning_status":"draft","note":"ਕਰਵਾਨ: read as 'swords' (karvar)."},{"gurmukhi":"ਏਕ ਲੈ ਬਾਨ ਕਮਾਨਨ ਤਾਨ ਕੈ ਤੂਰਨ ਤੇਜ ਤੁਰੰਗ ਤੁਰਾਏ।","roman":"Ek lai baan kamaanan taan kai tooran tej turang turaae |","meaning_en":"some, taking bows and drawing arrows, swiftly spurred on their fast horses.","page":198,"meaning_status":"draft"},{"gurmukhi":"ਧੂਰਿ ਉਡੀ ਖੁਰ ਪੂਰਨ ਤੇ ਪਥ ਊਰਧ ਹੁਇ ਰਵਿ ਮੰਡਲ ਛਾਏ।","roman":"Dhoori udee khur pooran te path ooradh hui ravi mandal chhaae |","meaning_en":"The dust from their hooves rose up from the road and covered the sun's disc,","page":198,"meaning_status":"draft"},{"gurmukhi":"ਮਾਨਹੁ ਫੇਰ ਰਚੇ ਬਿਧਿ ਲੋਕ ਧਰਾ ਖਟ ਆਠ ਅਕਾਸ ਬਨਾਏ। ੧੪੭।","roman":"Maanhu pher rache bidhi lok dharaa khat aath akaas banaae | 147 |","meaning_en":"as if the Creator had made the worlds anew: six earths below and eight heavens above. 147.","page":198,"meaning_status":"draft","note":"ਖਟ ਆਠ: 'six (and) eight'; i.e. dust raised a new sky; reading uncertain."}]},{"type":"verse","number":[148],"number_text":"੧੪੮।","page":199,"lines":[{"gurmukhi":"ਚੰਡ ਪ੍ਰਚੰਡ ਕੁਵੰਡ ਲੈ ਬਾਨਨਿ ਦੈਤਨ ਕੇ ਤਨ ਤੂਲਿ ਜਿਉ ਤੂੰਬੇ।","roman":"Chand prachand kuvand lai baanni daitan ke tan tooli jiu toonbe |","meaning_en":"Fierce Chandi, taking her bow, carded the demons' bodies with arrows like cotton.","page":199,"meaning_status":"draft","note":"ਤੂਲਿ ਜਿਉ ਤੂੰਬੇ: 'teased like cotton'."},{"gurmukhi":"ਮਾਰ ਗਇੰਦ ਦਏ ਕਰਵਾਰ ਲੈ ਦਾਨਵ ਮਾਨ ਗਇਓ ਉਡ ਪੂੰਬੇ।","roman":"Maar gaind dae karvaar lai daanav maan gaio ud poonbe |","meaning_en":"Taking her sword she slew the elephants; the demons' pride flew away like fluff.","page":199,"meaning_status":"draft","note":"ਪੂੰਬੇ: read as cotton fluff; uncertain."},{"gurmukhi":"ਬੀਰਨ ਕੇ ਸਿਰ ਕੀ ਸਿਤ ਪਾਗ ਚਲੀ ਬਹਿ ਸ੍ਰੋਨਤ ਊਪਰ ਖੂੰਬੇ।","roman":"Beeran ke sir kee sit paag chalee bahi sronat oopar khoonbe |","meaning_en":"The white turbans from the warriors' heads floated on the blood like mushrooms,","page":199,"meaning_status":"draft","note":"ਖੂੰਬੇ: mushrooms."},{"gurmukhi":"ਮਾਨਹੁ ਸਾਰਸੁਤੀ ਕੇ ਪ੍ਰਵਾਹ ਮੈ ਸੂਰਨ ਕੇ ਜਸ ਕੈ ਉਠੇ ਬੂੰਬੇ। ੧੪੮।","roman":"Maanhu saarsutee ke pravaah mai sooran ke jas kai uthe boonbe | 148 |","meaning_en":"as if in the stream of the Saraswati bubbles of the heroes' fame had risen. 148.","page":199,"meaning_status":"draft"}]},{"type":"verse","number":[149],"number_text":"੧੪੯।","page":199,"lines":[{"gurmukhi":"ਦੇਤਨ ਸਾਥ ਗਦਾ ਗਹਿ ਹਾਥਿ ਸੁ ਕ੍ਰੁਧ ਹ੍ਵੈ ਜੁਧੁ ਨਿਸੰਗ ਕਰਿਓ ਹੈ।","roman":"Detan saath gadaa gahi haathi su krudh hvai judhu nisang kario hai |","meaning_en":"Taking the mace in her hand, in anger she fought the demons fearlessly;","page":199,"meaning_status":"draft","note":"ਦੇਤਨ: printed so; read as ਦੈਤਨ 'demons'."},{"gurmukhi":"ਪਾਨਿ ਕ੍ਰਿਪਾਨ ਲਏ ਬਲਵਾਨ ਸੁ ਮਾਰ ਤਬੈ ਦਲ ਛਾਰ ਕਰਿਓ ਹੈ।","roman":"Paani kripaan lae balvaan su maar tabai dal chhaar kario hai |","meaning_en":"then, the mighty one, taking a sword in hand, she slew the army and reduced it to ashes.","page":199,"meaning_status":"draft"},{"gurmukhi":"ਪਾਗ ਸਮੇਤ ਗਿਰਿਓ ਸਿਰ ਏਕ ਕੋ ਭਾਉ ਇਹੇ ਕਬਿ ਤਾ ਕੋ ਧਰਿਓ ਹੈ।","roman":"Paag samet girio sir ek ko bhaau ihe kabi taa ko dhario hai |","meaning_en":"One head fell with its turban; the poet held this sense of it:","page":199,"meaning_status":"draft"},{"gurmukhi":"ਪੂਰਨਿ ਪੁੰਨ ਪਏ ਨਭ ਤੇ ਸੁ ਮਨੋ ਭੁਅ ਟੂਟ ਨਛਤ੍ਰ ਪਰਿਓ ਹੈ। ੧੪੯।","roman":"Poorni punn pae nabh te su mano bhua toot nachhatr pario hai | 149 |","meaning_en":"as if, when merits are spent, a star breaks from the sky and falls to earth. 149.","page":199,"meaning_status":"draft","note":"Belief that stars are beings who fall when their merit is exhausted."}]},{"type":"verse","number":[150],"number_text":"੧੫੦।","page":199,"lines":[{"gurmukhi":"ਬਾਰਿਦ ਬਾਰਨ ਜਿਉ ਨਿਰਵਾਰਿ ਮਹਾ ਬਲ ਧਾਰਿ ਤਬੇ ਇਹ ਕੀਆ।","roman":"Baarid baaran jiu nirvaari mahaa bal dhaari tabe ih keeaa |","meaning_en":"Scattering the elephants like clouds, the mighty one then did this:","page":199,"meaning_status":"draft","note":"ਬਾਰਿਦ ਬਾਰਨ: 'cloud-like elephants'; uncertain."},{"gurmukhi":"ਪਾਨਿ ਲੈ ਬਾਨ ਕਮਾਨ ਕੋ ਤਾਨਿ ਸੰਘਾਰ ਸਨੇਹ ਤੇ ਸ੍ਰਉਨਤ ਪੀਆ।","roman":"Paani lai baan kamaan ko taani sanghaar saneh te sraunat peeaa |","meaning_en":"taking bow and arrows in hand and drawing them, slaying them, she drank their blood with relish.","page":199,"meaning_status":"draft","note":"Subject may be the arrows that 'drank blood'; uncertain."},{"gurmukhi":"ਏਕ ਗਏ ਕੁਮਲਾਇ ਪਰਾਇ ਕੈ ਏਕਨ ਕੋ ਧਰਕਿਓ ਤਨਿ ਹੀਆ।","roman":"Ek gae kumlaai paraai kai ekan ko dharkio tani heeaa |","meaning_en":"Some withered away and fled; the hearts of others throbbed in their bodies.","page":199,"meaning_status":"draft"},{"gurmukhi":"ਚੰਡ ਕੇ ਬਾਨ ਕਿਧੋ ਕਰ ਭਾਨਹਿ ਦੇਖਿ ਕੈ ਦੈਤ ਗਈ ਦੁਤਿ ਦੀਆ। ੧੫੦।","roman":"Chand ke baan kidho kar bhaanhi dekhi kai dait gaee duti deeaa | 150 |","meaning_en":"Seeing Chandi's arrows, as if they were the sun's rays, the demons' lamp-like lustre faded. 150.","page":199,"meaning_status":"draft"}]},{"type":"verse","number":[151],"number_text":"੧੫੧।","page":199,"lines":[{"gurmukhi":"ਲੈ ਕਰ ਮੈ ਅਸਿ ਕੋਪ ਭਈ ਅਤਿ ਧਾਰ ਮਹਾ ਬਲ ਕੋ ਰਨ ਪਾਰਿਓ।","roman":"Lai kar mai asi kop bhaee ati dhaar mahaa bal ko ran paario |","meaning_en":"Taking the sword in hand, she grew very angry and, with great strength, fought the battle;","page":199,"meaning_status":"draft"},{"gurmukhi":"ਦਉਰ ਕੈ ਠਉਰ ਹਤੇ ਬਹੁ ਦਾਨਵ ਏਕ ਗਇੰਦ੍ਰ ਬਡੋ ਰਨਿ ਮਾਰਿਓ।","roman":"Daur kai thaur hate bahu daanav ek gaindr bado rani maario |","meaning_en":"rushing about, she slew many demons on the spot, and killed a great elephant in the battle.","page":199,"meaning_status":"draft"},{"gurmukhi":"ਕਉਤਕਿ ਤਾ ਛਬਿ ਕੋ ਰਨ ਪੇਖਿ ਤਬੈ ਕਬਿ ਇਉ ਮਨ ਮਧਿ ਬਿਚਾਰਿਓ।","roman":"Kautki taa chhabi ko ran pekhi tabai kabi iu man madhi bichaario |","meaning_en":"Seeing the wonder of this scene in the battle, the poet then thought in his mind:","page":199,"meaning_status":"draft"},{"gurmukhi":"ਸਾਗਰ ਬਾਂਧਨ ਕੇ ਸਮਏ ਨਲ ਮਾਨੋ ਪਹਾਰ ਉਖਾਰ ਕੇ ਡਾਰਿਓ। ੧੫੧।","roman":"Saagar baandhan ke samae nal maano pahaar ukhaar ke daario | 151 |","meaning_en":"as if, at the time of bridging the ocean, Nal had uprooted a mountain and thrown it down. 151.","page":199,"meaning_status":"draft","note":"Nal: the builder of Ram's bridge."}]},{"type":"heading","kind":"chhand","name":"ਦੋਹਰਾ","gurmukhi":"ਦੋਹਰਾ","roman":"Dohraa","meaning_en":"Dohra.","page":199,"meaning_status":"draft"},{"type":"verse","number":[152],"number_text":"੧੫੨।","page":199,"lines":[{"gurmukhi":"ਮਾਰ ਜਬੈ ਸੈਨਾ ਲਈ ਤਬੈ ਦੈਤ ਇਹ ਕੀਨ।","roman":"Maar jabai sainaa laee tabai dait ih keen |","meaning_en":"When she had slain his army, then the demon did this:","page":199,"meaning_status":"draft"},{"gurmukhi":"ਸਸਤ੍ਰ ਧਾਰ ਕਰਿ ਚੰਡਿ ਕੇ ਬਧਿਬੇ ਕੋ ਮਨ ਦੀਨ। ੧੫੨।","roman":"Sasatr dhaar kari chandi ke badhibe ko man deen | 152 |","meaning_en":"taking weapons in hand, he set his mind on killing Chandi. 152.","page":199,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਸ੍ਵੈਯਾ","gurmukhi":"ਸ੍ਵੈਯਾ","roman":"Svaiyaa","meaning_en":"Savaiya.","page":199,"meaning_status":"draft"},{"type":"verse","number":[153],"number_text":"੧੫੩।","page":199,"lines":[{"gurmukhi":"ਬਾਹਨਿ ਸਿੰਘ ਭਇਆਨਕ ਰੂਪ ਲਖਿਓ ਸਭ ਦੈਤ ਮਹਾ ਡਰ ਪਾਇਓ।","roman":"Baahni singh bhaiaanak roop lakhio sabh dait mahaa dar paaio |","meaning_en":"Seeing the fearsome form of her lion mount, all the demons were greatly afraid.","page":199,"meaning_status":"draft"},{"gurmukhi":"ਸੰਖ ਲੀਏ ਕਰਿ ਚਕ੍ਰ ਅਉ ਬਕ੍ਰ ਸਰਾਸਨ ਪਤ੍ਰ ਬਚਿਤ੍ਰ ਬਨਾਇਓ।","roman":"Sankh lee'e kari chakr au bakr saraasan patr bachitr banaaio |","meaning_en":"She held a conch in her hand, a discus, and a curved bow fitted with arrows, wondrously made.","page":199,"meaning_status":"draft","note":"ਪਤ੍ਰ: 'feathered (arrows)'; uncertain."},{"gurmukhi":"ਧਾਇ ਭੁਜਾ ਬਲ ਆਪਨ ਹ੍ਵੈ ਹਮ ਸੋ ਤਿਨਯੌ ਅਤਿ ਜੁਧੁ ਮਚਾਇਓ।","roman":"Dhaai bhujaa bal aapan hvai ham so tinyau ati judhu machaaio |","meaning_en":"'Rushing forward by the strength of her own arms, she has waged a fierce war with us like this.'","page":199,"meaning_status":"draft","note":"Line read as Raktabij's words; uncertain."},{"gurmukhi":"ਕ੍ਰੋਧ ਕੈ ਸ੍ਰਉਣਤ ਬਿੰਦ ਕਹੈ ਰਨਿ ਇਆਹੀ ਤੇ ਚੰਡਿਕਾ ਨਾਮ ਕਹਾਇਓ।੧੫੩।","roman":"Krodh kai sraunat bind kahai rani iaahee te chandikaa naam kahaaio | 153 |","meaning_en":"In anger Raktabij says on the field, 'That is why she is called Chandika.' 153.","page":199,"meaning_status":"draft","note":"Reading uncertain."}]},{"type":"verse","number":[154],"number_text":"੧੫੪।","page":200,"lines":[{"gurmukhi":"ਮਾਰਿ ਲਇਓ ਦਲਿ ਅਉਰ ਭਜਿਓ ਤਬ ਕੋਪ ਕੇ ਆਪਨ ਹੀ ਸੁ ਭਿਰਿਓ ਹੈ।","roman":"Maari laio dali aur bhajio tab kop ke aapan hee su bhirio hai |","meaning_en":"She slew his army and the rest fled; then in anger he himself fought;","page":200,"meaning_status":"draft"},{"gurmukhi":"ਚੰਡਿ ਪ੍ਰਚੰਡਿ ਸੋ ਜੁਧੁ ਕਰਿਓ ਅਸਿ ਹਾਥਿ ਛੁਟਿਓ ਮਨ ਨਾਹਿ ਗਿਰਿਓ ਹੈ।","roman":"Chandi prachandi so judhu kario asi haathi chhutio man naahi girio hai |","meaning_en":"he fought fierce Chandi; the sword slipped from his hand, but his spirit did not fall.","page":200,"meaning_status":"draft"},{"gurmukhi":"ਲੈ ਕੇ ਕੁਵੰਡ ਕਰੰ ਬਲ ਧਾਰ ਕੈ ਸ੍ਰੋਨ ਸਮੂਹ ਮੈ ਐਸੇ ਤਰਿਓ ਹੈ।","roman":"Lai ke kuvand karan bal dhaar kai sron samooh mai aise tario hai |","meaning_en":"Taking a bow in hand with all his strength, he moved through the mass of blood like this,","page":200,"meaning_status":"draft"},{"gurmukhi":"ਦੇਵ ਅਦੇਵ ਸਮੁੰਦ੍ਰ ਮਥਿਓ ਮਾਨੋ ਮੇਰ ਕੋ ਮਧਿ ਧਰਿਓ ਸੁ ਫਿਰਿਓ ਹੈ। ੧੫੪।","roman":"Dev adev samundr mathio maano mer ko madhi dhario su phirio hai | 154 |","meaning_en":"as when the gods and demons churned the ocean, with Meru set in the middle, turning. 154.","page":200,"meaning_status":"draft"}]},{"type":"verse","number":[155],"number_text":"੧੫੫।","page":200,"lines":[{"gurmukhi":"ਕ੍ਰੁਧ ਕੈ ਜੁਧ ਕੇ ਦੈਤ ਬਲੀ ਨਦ ਸ੍ਰੋਨ ਕੋ ਤੈਰ ਕੇ ਪਾਰ ਪਧਾਰਿਓ।","roman":"Krudh kai judh ke dait balee nad sron ko tair ke paar padhaario |","meaning_en":"In anger the mighty demon swam across the river of blood for battle;","page":200,"meaning_status":"draft"},{"gurmukhi":"ਲੈ ਕਰਵਾਰ ਅਉ ਢਾਰ ਸੰਭਾਰ ਕੈ ਸਿੰਘ ਕੋ ਦਉਰ ਕੈ ਜਾਇ ਹਕਾਰਿਓ।","roman":"Lai karvaar au dhaar sanbhaar kai singh ko daur kai jaai hakaario |","meaning_en":"taking sword and shield, he rushed forward and challenged the lion.","page":200,"meaning_status":"draft"},{"gurmukhi":"ਆਵਤ ਪੇਖ ਕੈ ਚੰਡਿ ਕੁਵੰਡ ਤੇ ਬਾਨ ਲਗਿਓ ਤਨ ਮੂਰਛ ਪਾਰਿਓ।","roman":"Aavat pekh kai chandi kuvand te baan lagio tan moorachh paario |","meaning_en":"Seeing him coming, Chandi struck his body with an arrow from her bow, and he fell senseless,","page":200,"meaning_status":"draft"},{"gurmukhi":"ਰਾਮ ਕੇ ਭ੍ਰਾਤਨ ਜਿਉ ਹਨੂਮਾਨ ਕੋ ਸੈਲ ਸਮੇਤ ਧਰਾ ਪਰ ਡਾਰਿਓ। ੧੫੫।","roman":"Raam ke bhraatan jiu hanoomaan ko sail samet dharaa par daario | 155 |","meaning_en":"as Ram's brother (Bharat) brought down Hanuman to the earth along with the mountain. 155.","page":200,"meaning_status":"draft","note":"ਭ੍ਰਾਤਨ: read as Bharat, who shot Hanuman carrying the mountain."}]},{"type":"verse","number":[156],"number_text":"੧੫੬।","page":200,"lines":[{"gurmukhi":"ਫੇਰ ਉਠਿਓ ਕਰਿ ਲੈ ਕਰਵਾਰ ਕੋ ਚੰਡ ਪ੍ਰਚੰਡ ਸਿਉ ਜੁਧ ਕਰਿਓ ਹੈ।","roman":"Pher uthio kari lai karvaar ko chand prachand siu judh kario hai |","meaning_en":"He rose again, took his sword in hand, and fought with fierce Chandi.","page":200,"meaning_status":"draft"},{"gurmukhi":"ਘਾਇਲ ਕੈ ਤਨ ਕੇਹਰ ਤੇ ਬਹਿ ਸ੍ਰਉਨ ਸਮੂਹ ਧਰਾਨਿ ਪਰਿਓ ਹੈ।","roman":"Ghaail kai tan kehar te bahi sraun samooh dharaani pario hai |","meaning_en":"He wounded the lion, and from its body much blood flowed to the ground.","page":200,"meaning_status":"draft"},{"gurmukhi":"ਸੋ ਉਪਮਾ ਕਬਿ ਨੇ ਬਰਨੀ ਮਨ ਕੀ ਹਰਨੀ ਤਿਹ ਨਾਉ ਧਰਿਓ ਹੈ।","roman":"So upmaa kabi ne barnee man kee harnee tih naau dhario hai |","meaning_en":"The poet described the simile; he named it 'the stealer of the mind':","page":200,"meaning_status":"draft"},{"gurmukhi":"ਗੇਰੂ ਨਗੰ ਪਰ ਕੈ ਬਰਖਾ ਧਰਨੀ ਪਰਿ ਮਾਨਹੁ ਰੰਗ ਢਰਿਓ ਹੈ। ੧੫੬।","roman":"Geroo nagan par kai barkhaa dharnee pari maanhu rang dhario hai | 156 |","meaning_en":"as if rain on a mountain of red ochre had poured its colour onto the earth. 156.","page":200,"meaning_status":"draft"}]},{"type":"verse","number":[157],"number_text":"੧੫੭।","page":200,"lines":[{"gurmukhi":"ਸ੍ਰੋਣਤ ਬਿੰਦੂ ਸੋ ਚੰਡਿ ਪ੍ਰਚੰਡ ਸੁ ਜੁਧ ਕਰਿਓ ਰਨ ਮਧ ਰੁਹੇਲੀ।","roman":"Sronat bindoo so chandi prachand su judh kario ran madh ruhelee |","meaning_en":"Fierce Chandi fought with Raktabij on the field, in her wrath,","page":200,"meaning_status":"draft","note":"ਰੁਹੇਲੀ: read as 'in anger' or 'valiant'; uncertain."},{"gurmukhi":"ਪੈ ਦਲ ਮੈ ਦਲ ਮੀਜ ਦਇਓ ਤਿਲ ਤੇ ਜਿਮੁ ਤੇਲ ਨਿਕਾਰਤ ਤੇਲੀ।","roman":"Pai dal mai dal meej daio til te jimu tel nikaarat telee |","meaning_en":"entering the army, she crushed it as an oil-presser presses oil from sesame.","page":200,"meaning_status":"draft"},{"gurmukhi":"ਸ੍ਰੋਉਣ ਪਰਿਓ ਧਰਨੀ ਪਰ ਚ੍ਵੈ ਰੰਗਰੇਜ ਕੀ ਰੇਨੀ ਜਿਉ ਫੂਟ ਕੈ ਫੈਲੀ।","roman":"Sroun pario dharnee par chvai rangrej kee renee jiu phoot kai phailee |","meaning_en":"The blood dripped onto the earth and spread like a dyer's vat that has burst.","page":200,"meaning_status":"draft","note":"ਰੇਨੀ: a dye vessel; uncertain."},{"gurmukhi":"ਘਾਉ ਲਸੈ ਤਨ ਦੈਤ ਕੇ ਯੌ ਜਨੁ ਦੀਪਕ ਮਧਿ ਫਨੂਸ ਕੀ ਥੈਲੀ। ੧੫੭।","roman":"Ghaau lasai tan dait ke yau janu deepak madhi phanoos kee thailee | 157 |","meaning_en":"The wounds on the demon's body gleam like a lamp within a glass lantern. 157.","page":200,"meaning_status":"draft","note":"ਫਨੂਸ: a glass shade (fanoos)."}]},{"type":"verse","number":[158],"number_text":"੧੫੮।","page":200,"lines":[{"gurmukhi":"ਸ੍ਰਉਣਤ ਬਿੰਦ ਕੋ ਸ੍ਰਉਣ ਪਰਿਓ ਧਰਿ ਸ੍ਰਉਨਤ ਬਿੰਦ ਅਨੇਕ ਭਏ ਹੈ।","roman":"Sraunat bind ko sraun pario dhari sraunat bind anek bhae hai |","meaning_en":"The blood of Raktabij fell on the ground, and many Raktabijs arose.","page":200,"meaning_status":"draft"},{"gurmukhi":"ਚੰਡਿ ਪ੍ਰਚੰਡ ਕੁਵੰਡਿ ਸੰਭਾਰਿ ਕੇ ਬਾਨਨ ਸਾਥਿ ਸੰਘਾਰ ਦਏ ਹੈ।","roman":"Chandi prachand kuvandi sanbhaari ke baanan saathi sanghaar dae hai |","meaning_en":"Fierce Chandi took up her bow and destroyed them with arrows.","page":200,"meaning_status":"draft"},{"gurmukhi":"ਸ੍ਰਉਨ ਸਮੂਹ ਸਮਾਇ ਗਏ ਬਹੁਰੋ ਸੁ ਭਏ ਹਤਿ ਫੇਰਿ ਲਏ ਹੈ।","roman":"Sraun samooh samaai gae bahuro su bhae hati pheri lae hai |","meaning_en":"Masses of blood merged again, and they arose again, and were slain again,","page":200,"meaning_status":"draft"},{"gurmukhi":"ਬਾਰਿਦ ਧਾਰ ਪਰੈ ਧਰਨੀ ਮਾਨੋ ਬਿਬੰਰ ਹ੍ਵੈ ਮਿਟ ਕੈ ਜੁ ਗਏ ਹੈ। ੧੫੮।","roman":"Baarid dhaar parai dharnee maano bibanr hvai mit kai ju gae hai | 158 |","meaning_en":"as streams of rain fall on the earth, form bubbles and vanish. 158.","page":200,"meaning_status":"draft","note":"ਬਿਬੰਰ: printed so; read as 'bubbles'; uncertain."}]},{"type":"verse","number":[159],"number_text":"੧੫੯।","page":200,"lines":[{"gurmukhi":"ਜੇਤਕ ਸ੍ਰਉਨ ਕੀ ਬੂੰਦ ਗਿਰੈ ਰਨਿ ਤੇਤਕ ਸ੍ਰਉਨਤ ਬਿੰਦ ਹ੍ਵੈ ਆਈ।","roman":"Jetak sraun kee boond girai rani tetak sraunat bind hvai aaee |","meaning_en":"As many drops of blood as fell on the field, so many Raktabijs appeared;","page":200,"meaning_status":"draft"},{"gurmukhi":"ਮਾਰ ਹੀ ਮਾਰ ਪੁਕਾਰਿ ਹਕਾਰ ਕੈ ਚੰਡਿ ਪ੍ਰਚੰਡਿ ਕੇ ਸਾਮੁਹਿ ਧਾਈ।","roman":"Maar hee maar pukaari hakaar kai chandi prachandi ke saamuhi dhaaee |","meaning_en":"crying 'Kill! Kill!' and shouting, they rushed before fierce Chandi.","page":200,"meaning_status":"draft"},{"gurmukhi":"ਪੇਖਿ ਕੈ ਕੌਤੁਕ ਤਾ ਛਿਨ ਮੈ ਕਵਿ ਨੇ ਮਨ ਮੈ ਉਪਮਾ ਠਹਰਾਈ।","roman":"Pekhi kai kautuk taa chhin mai kavi ne man mai upmaa thahraaee |","meaning_en":"Seeing the marvel at that moment, the poet fixed this simile in his mind:","page":200,"meaning_status":"draft"},{"gurmukhi":"ਮਾਨਹੁ ਸੀਸ ਮਹਲ ਕੇ ਬੀਚ ਸੁ ਮੂਰਤਿ ਏਕ ਅਨੇਕ ਕੀ ਝਾਈ। ੧੫੯।","roman":"Maanhu sees mahal ke beech su moorti ek anek kee jhaaee | 159 |","meaning_en":"as if in a palace of mirrors one image cast the reflections of many. 159.","page":200,"meaning_status":"draft"}]},{"type":"verse","number":[160],"number_text":"੧੬੦।","page":201,"lines":[{"gurmukhi":"ਸ੍ਰਉਨਤ ਬਿੰਦ ਅਨੇਕ ਉਠੇ ਰਨਿ ਕ੍ਰੁਧ ਕੈ ਜੁਧ ਕੋ ਫੇਰ ਜੁਟੈ ਹੈ।","roman":"Sraunat bind anek uthe rani krudh kai judh ko pher jutai hai |","meaning_en":"Many Raktabijs arose on the field and in anger joined battle again.","page":201,"meaning_status":"draft"},{"gurmukhi":"ਚੰਡਿ ਪ੍ਰਚੰਡਿ ਕਮਾਨ ਤੇ ਬਾਨ ਸੁ ਭਾਨੁ ਕੀ ਅੰਸ ਸਮਾਨ ਛੁਟੈ ਹੈ।","roman":"Chandi prachandi kamaan te baan su bhaanu kee ans samaan chhutai hai |","meaning_en":"From fierce Chandi's bow arrows flew like rays of the sun;","page":201,"meaning_status":"draft"},{"gurmukhi":"ਮਾਰਿ ਬਿਦਾਰ ਦਏ ਸੁ ਭਏ ਫਿਰਿ ਲੈ ਮੁੰਗਰਾ ਜਿਮੁ ਧਾਨ ਕੁਟੈ ਹੈ।","roman":"Maari bidaar dae su bhae phiri lai mungraa jimu dhaan kutai hai |","meaning_en":"she slew and tore them apart; they arose again, and she pounded them as paddy is beaten with a pestle.","page":201,"meaning_status":"draft"},{"gurmukhi":"ਚੰਡ ਦਏ ਸਿਰ ਖੰਡ ਜੁਦੇ ਕਰਿ ਬਿਲਨ ਤੇ ਜਨ ਬਿਲ ਤੁਟੈ ਹੈ। ੧੬੦।","roman":"Chand dae sir khand jude kari bilan te jan bil tutai hai | 160 |","meaning_en":"Chandi cut their heads into pieces and separated them, as bael fruits fall broken from the bael trees. 160.","page":201,"meaning_status":"draft"}]},{"type":"verse","number":[161],"number_text":"੧੬੧।","page":201,"lines":[{"gurmukhi":"ਸ੍ਰਉਨਤ ਬਿੰਦ ਅਨੇਕ ਭਏ ਅਸਿ ਲੈ ਕਰਿ ਚੰਡਿ ਸੁ ਐਸੇ ਉਠੇ ਹੈ।","roman":"Sraunat bind anek bhae asi lai kari chandi su aise uthe hai |","meaning_en":"Many Raktabijs arose and, swords in hand, rose against Chandi thus:","page":201,"meaning_status":"draft"},{"gurmukhi":"ਬੂੰਦਨ ਤੇ ਉਠਿ ਕੈ ਬਹੁ ਦਾਨਵ ਬਾਨਨ ਬਾਰਿਦ ਜਾਨੁ ਵੁਠੇ ਹੈ।","roman":"Boondan te uthi kai bahu daanav baanan baarid jaanu vuthe hai |","meaning_en":"rising from the drops, many demons rained down arrows like clouds.","page":201,"meaning_status":"draft"},{"gurmukhi":"ਫੇਰਿ ਕੁਵੰਡਿ ਪ੍ਰਚੰਡਿ ਸੰਭਾਰ ਕੈ ਬਾਨ ਪ੍ਰਹਾਰ ਸੰਘਾਰ ਸੁਟੇ ਹੈ।","roman":"Pheri kuvandi prachandi sanbhaar kai baan prahaar sanghaar sute hai |","meaning_en":"Again, taking up her fierce bow, she shot arrows and laid them dead.","page":201,"meaning_status":"draft"},{"gurmukhi":"ਐਸੇ ਉਠੇ ਫਿਰਿ ਸ੍ਰਉਨ ਤੇ ਦੈਤ ਸੁ ਮਾਨਹੁ ਸੀਤ ਤੇ ਰੋਮ ਉਠੇ ਹੈ। ੧੬੧।","roman":"Aise uthe phiri sraun te dait su maanhu seet te rom uthe hai | 161 |","meaning_en":"Again demons rose from the blood, as hairs rise on the skin from the cold. 161.","page":201,"meaning_status":"draft"}]},{"type":"verse","number":[162],"number_text":"੧੬੨।","page":201,"lines":[{"gurmukhi":"ਸ੍ਰਉਨਤ ਬਿੰਦ ਭਏ ਇਕਠੇ ਬਰ ਚੰਡਿ ਪ੍ਰਚੰਡ ਕੇ ਘੇਰਿ ਲਇਓ ਹੈ।","roman":"Sraunat bind bhae ikthe bar chandi prachand ke gheri laio hai |","meaning_en":"The Raktabijs gathered together and surrounded the mighty, fierce Chandi.","page":201,"meaning_status":"draft"},{"gurmukhi":"ਚੰਡਿ ਅਉ ਸਿੰਘ ਦੁਹੂੰ ਮਿਲ ਕੈ ਸਬ ਦੈਤਨ ਕੋ ਦਲ ਮਾਰ ਦਇਓ ਹੈ।","roman":"Chandi au singh duhoon mil kai sab daitan ko dal maar daio hai |","meaning_en":"Chandi and the lion together slew the whole army of demons.","page":201,"meaning_status":"draft"},{"gurmukhi":"ਫੇਰਿ ਉਠੇ ਧੁਨਿ ਕੇ ਕਰਿ ਕੈ ਸੁਨਿ ਕੈ ਮੁਨਿ ਕੋ ਛੁਟਿ ਧਿਆਨੁ ਗਇਓ ਹੈ।","roman":"Pheri uthe dhuni ke kari kai suni kai muni ko chhuti dhiaanu gaio hai |","meaning_en":"They rose again, with a great noise; hearing it, the sage's meditation was broken.","page":201,"meaning_status":"draft"},{"gurmukhi":"ਭੂਲ ਗਏ ਸੁਰ ਕੇ ਅਸਵਾਨ ਗੁਮਾਨ ਨ ਸ੍ਰਉਨਤ ਬਿੰਦ ਗਇਓ ਹੈ। ੧੬੨।","roman":"Bhool gae sur ke asvaan gumaan na sraunat bind gaio hai | 162 |","meaning_en":"The gods forgot their horses; yet Raktabij's pride did not go. 162.","page":201,"meaning_status":"draft","note":"ਸੁਰ ਕੇ ਅਸਵਾਨ: 'the gods' horses'; perhaps 'the gods lost their senses'; uncertain."}]},{"type":"heading","kind":"chhand","name":"ਦੋਹਰਾ","gurmukhi":"ਦੋਹਰਾ","roman":"Dohraa","meaning_en":"Dohra.","page":201,"meaning_status":"draft"},{"type":"verse","number":[163],"number_text":"੧੬੩।","page":201,"lines":[{"gurmukhi":"ਰਕਤਬੀਜ ਸੋ ਚੰਡਿਕਾ ਇਉ ਕੀਨੋ ਬਰ ਜੁਧੁ।","roman":"Rakatbeej so chandikaa iu keeno bar judhu |","meaning_en":"Thus Chandika fought a mighty battle with Raktabij;","page":201,"meaning_status":"draft"},{"gurmukhi":"ਅਗਨਤ ਭਏ ਦਾਨਵ ਤਬੈ ਕਛੁ ਨ ਬਸਾਇਓ ਕ੍ਰੁਧ। ੧੬੩।","roman":"Agnat bhae daanav tabai kachhu na basaaio krudh | 163 |","meaning_en":"then countless demons arose; her anger could do nothing. 163.","page":201,"flags":[{"code":"0x71","reason":"subjoined letter typed after the vowel/nasal sign; put in Unicode order (same printed shape)"}],"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਸ੍ਵੈਯਾ","gurmukhi":"ਸ੍ਵੈਯਾ","roman":"Svaiyaa","meaning_en":"Savaiya.","page":201,"meaning_status":"draft"},{"type":"verse","number":[164],"number_text":"੧੬੪।","page":201,"lines":[{"gurmukhi":"ਪੇਖਿ ਦਸੋ ਦਿਸ ਤੇ ਬਹੁ ਦਾਨਵ ਚੰਡਿ ਪ੍ਰਚੰਡ ਤਚੀ ਅਖੀਆ।","roman":"Pekhi daso dis te bahu daanav chandi prachand tachee akheeaa |","meaning_en":"Seeing many demons on all ten sides, fierce Chandi's eyes blazed.","page":201,"meaning_status":"draft"},{"gurmukhi":"ਤਬ ਲੈ ਕੇ ਕ੍ਰਿਪਾਨ ਜੁ ਕਾਟ ਦਏ ਅਰਿ ਫੂਲ ਗੁਲਾਬ ਕੀ ਜਿਉ ਪਖੀਆ।","roman":"Tab lai ke kripaan ju kaat dae ari phool gulaab kee jiu pakheeaa |","meaning_en":"Then, taking her sword, she cut down the enemies like rose petals.","page":201,"meaning_status":"draft"},{"gurmukhi":"ਸ੍ਰਉਨ ਕੀ ਛੀਟ ਪਰੀ ਤਨ ਚੰਡਿ ਕੇ ਸੋ ਉਪਮਾ ਕਵਿ ਨੇ ਲਖੀਆ।","roman":"Sraun kee chheet paree tan chandi ke so upmaa kavi ne lakheeaa |","meaning_en":"Drops of blood fell on Chandi's body; the poet saw this simile:","page":201,"meaning_status":"draft"},{"gurmukhi":"ਜਨੁ ਕੰਚਨ ਮੰਦਿਰ ਮੈ ਜਰੀਆ ਜਰਿ ਲਾਲ ਮਨੀ ਜੁ ਬਨਾ ਰਖੀਆ। ੧੬੪।","roman":"Janu kanchan mandir mai jareeaa jari laal manee ju banaa rakheeaa | 164 |","meaning_en":"as if a jeweller had set red rubies into a golden temple. 164.","page":201,"meaning_status":"draft"}]},{"type":"verse","number":[165],"number_text":"੧੬੫।","page":201,"lines":[{"gurmukhi":"ਕ੍ਰੁਧ ਕੈ ਜੁਧ ਕਰਿਓ ਬਹੁ ਚੰਡਿ ਨ ਏਤੋ ਕਰਿਓ ਮਧੁ ਸੋ ਅਬਿਨਾਸੀ।","roman":"Krudh kai judh kario bahu chandi na eto kario madhu so abinaasee |","meaning_en":"In anger Chandi fought much; not even the Imperishable (Vishnu) fought so much with Madhu.","page":201,"meaning_status":"draft"},{"gurmukhi":"ਦੈਤਨ ਕੇ ਬਧ ਕਾਰਨ ਕੋ ਨਿਜ ਭਾਲ ਤੇ ਜੁਆਲ ਕੀ ਲਾਟ ਨਿਕਾਸੀ।","roman":"Daitan ke badh kaaran ko nij bhaal te juaal kee laat nikaasee |","meaning_en":"To slay the demons, she brought forth a flame of fire from her own forehead.","page":201,"meaning_status":"draft"},{"gurmukhi":"ਕਾਲੀ ਪ੍ਰਤਛ ਭਈ ਤਿਹ ਤੇ ਰਨਿ ਫੈਲ ਰਹੀ ਭਯ ਭੀਰੁ ਪ੍ਰਭਾ ਸੀ।","roman":"Kaalee pratachh bhaee tih te rani phail rahee bhay bheeru prabhaa see |","meaning_en":"From it Kali appeared, spreading on the field like the radiance of terror itself,","page":201,"meaning_status":"draft","note":"ਭਯ ਭੀਰੁ ਪ੍ਰਭਾ ਸੀ: 'a radiance that frightens the timid'; uncertain."},{"gurmukhi":"ਮਾਨਹੁ ਸ੍ਰਿੰਗ ਸੁਮੇਰ ਕੋ ਫੋਰਿ ਕੈ ਧਾਰ ਪਰੀ ਧਰਿ ਪੈ ਜਮੁਨਾ ਸੀ। ੧੬੫।","roman":"Maanhu sring sumer ko phori kai dhaar paree dhari pai jamunaa see | 165 |","meaning_en":"as if bursting from the peak of Sumeru, a stream like the Yamuna had fallen to the earth. 165.","page":201,"meaning_status":"draft"}]},{"type":"verse","number":[166],"number_text":"੧੬੬।","page":201,"lines":[{"gurmukhi":"ਮੇਰੁ ਹਲਿਓ ਦਹਲਿਓ ਸੁਰਲੋਕੁ ਦਸੋ ਦਿਸ ਭੂਧਰ ਭਾਜਤ ਭਾਰੀ।","roman":"Meru halio dahlio surloku daso dis bhoodhar bhaajat bhaaree |","meaning_en":"Meru shook, the world of the gods trembled, the heavy mountains in the ten directions fled;","page":201,"meaning_status":"draft"},{"gurmukhi":"ਚਾਲਿ ਪਰਿਓ ਤਿਹ ਚਉਦਹਿ ਲੋਕ ਮੈ ਬ੍ਰਹਮ ਭਇਓ ਮਨ ਮੈ ਭ੍ਰਮ ਭਾਰੀ।","roman":"Chaali pario tih chaudhi lok mai braham bhaio man mai bhram bhaaree |","meaning_en":"there was commotion in the fourteen worlds; Brahma was greatly bewildered in his mind.","page":201,"meaning_status":"draft"},{"gurmukhi":"ਧਿਆਨ ਰਹਿਓ ਨ ਜਟੀ ਸੁ ਫਟੀ ਧਰਿ ਯੌ ਬਲਿ ਕੈ ਰਨ ਮੈ ਕਿਲਕਾਰੀ।","roman":"Dhiaan rahio na jatee su phatee dhari yau bali kai ran mai kilkaaree |","meaning_en":"The matted-haired one (Shiva) lost his meditation; the earth split, so mightily did she shriek in battle.","page":202,"meaning_status":"draft"},{"gurmukhi":"ਦੈਤਨ ਕੇ ਬਧਿ ਕਾਰਨ ਕੋ ਕਰਿ ਕਾਲ ਸੀ ਕਾਲੀ ਕ੍ਰਿਪਾਨ ਸੰਭਾਰੀ। ੧੬੬।","roman":"Daitan ke badhi kaaran ko kari kaal see kaalee kripaan sanbhaaree | 166 |","meaning_en":"To slay the demons, Kali, like Death, took up the sword in her hand. 166.","page":202,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਦੋਹਰਾ","gurmukhi":"ਦੋਹਰਾ","roman":"Dohraa","meaning_en":"Dohra.","page":202,"meaning_status":"draft"},{"type":"verse","number":[167],"number_text":"੧੬੭।","page":202,"lines":[{"gurmukhi":"ਚੰਡੀ ਕਾਲੀ ਦੁਹੂੰ ਮਿਲਿ ਕੀਨੋ ਇਹੈ ਬਿਚਾਰ।","roman":"Chandee kaalee duhoon mili keeno ihai bichaar |","meaning_en":"Chandi and Kali together made this plan:","page":202,"meaning_status":"draft"},{"gurmukhi":"ਹਉ ਹਨਿ ਹੋ ਤੂ ਸ੍ਰਉਨ ਪੀ ਅਰਿ ਦਲਿ ਡਾਰਹਿ ਮਾਰਿ। ੧੬੭।","roman":"Hau hani ho too sraun pee ari dali daarhi maari | 167 |","meaning_en":"'I will strike, you drink the blood; thus we will destroy the enemy army.' 167.","page":202,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਸ੍ਵੈਯਾ","gurmukhi":"ਸ੍ਵੈਯਾ","roman":"Svaiyaa","meaning_en":"Savaiya.","page":202,"meaning_status":"draft"},{"type":"verse","number":[168],"number_text":"੧੬੮।","page":202,"lines":[{"gurmukhi":"ਕਾਲੀ ਅਉ ਕੇਹਰਿ ਸੰਗਿ ਲੈ ਚੰਡਿ ਸੁ ਘੇਰੇ ਸਬੈ ਬਨ ਜੈਸੇ ਦਵਾ ਪੈ।","roman":"Kaalee au kehri sangi lai chandi su ghere sabai ban jaise davaa pai |","meaning_en":"Taking Kali and the lion with her, Chandi surrounded them all, as a forest fire surrounds the forest.","page":202,"meaning_status":"draft"},{"gurmukhi":"ਚੰਡਿ ਕੇ ਬਾਨਨ ਤੇਜ ਪ੍ਰਭਾਵ ਤੇ ਦੈਤ ਜਰੈ ਜੈਸੇ ਈਟ ਅਵਾ ਪੈ।","roman":"Chandi ke baanan tej prabhaav te dait jarai jaise eet avaa pai |","meaning_en":"By the burning power of Chandi's arrows the demons burned like bricks in a kiln.","page":202,"meaning_status":"draft"},{"gurmukhi":"ਕਾਲਿਕਾ ਸ੍ਰਉਨ ਪੀਓ ਤਿਨ ਕੋ ਕਵਿ ਨੇ ਮਨ ਮੈ ਲੀਯੋ ਭਾਉ ਭਵਾ ਪੈ।","roman":"Kaalikaa sraun peeo tin ko kavi ne man mai leeyo bhaau bhavaa pai |","meaning_en":"Kalika drank their blood; the poet conceived this sense of it:","page":202,"meaning_status":"draft","note":"ਭਵਾ ਪੈ: unclear; perhaps 'about Bhavani'; uncertain."},{"gurmukhi":"ਮਾਨਹੁ ਸਿੰਧੁ ਕੇ ਨੀਰ ਸਬੈ ਮਿਲਿ ਧਾਇ ਕੈ ਜਾਇ ਪਰੋ ਹੈ ਤਵਾ ਪੈ। ੧੬੮।","roman":"Maanhu sindhu ke neer sabai mili dhaai kai jaai paro hai tavaa pai | 168 |","meaning_en":"as if all the waters of the ocean together had rushed and fallen onto a hot griddle. 168.","page":202,"meaning_status":"draft"}]},{"type":"verse","number":[169],"number_text":"੧੬੯।","page":202,"lines":[{"gurmukhi":"ਚੰਡਿ ਹਨੇ ਅਰੁ ਕਾਲਿਕਾ ਕੋਪ ਕੈ ਸ੍ਰਉਨਤ ਬਿੰਦਨ ਸੋ ਇਹ ਕੀਨੋ।","roman":"Chandi hane aru kaalikaa kop kai sraunat bindan so ih keeno |","meaning_en":"Chandi struck, and Kalika in anger did this to the Raktabijs:","page":202,"meaning_status":"draft"},{"gurmukhi":"ਖਗ ਸੰਭਾਰ ਹਕਾਰ ਤਬੈ ਕਿਲਕਾਰ ਬਿਦਾਰ ਸਭੈ ਦਲੁ ਦੀਨੋ।","roman":"Khag sanbhaar hakaar tabai kilkaar bidaar sabhai dalu deeno |","meaning_en":"taking up her sword, with a shout and a shriek she tore apart the whole army.","page":202,"meaning_status":"draft"},{"gurmukhi":"ਆਮਿਖ ਸ੍ਰੋਨ ਅਚਿਓ ਬਹੁ ਕਾਲਿਕਾ ਤਾ ਛਬਿ ਮੈ ਕਵਿ ਇਉ ਮਨਿ ਚੀਨੋ।","roman":"Aamikh sron achio bahu kaalikaa taa chhabi mai kavi iu mani cheeno |","meaning_en":"Kalika devoured much flesh and blood; at that sight the poet perceived it thus,","page":202,"meaning_status":"draft","note":"ਆਮਿਖ: flesh."},{"gurmukhi":"ਮਾਨੋ ਛੁਧਾਤਰੁ ਹੁਇ ਕੈ ਮਨੁਛ ਸੁ ਸਾਲਨ ਲਾਸਹਿ ਸੋ ਬਹੁ ਪੀਨੋ। ੧੬੯।","roman":"Maano chhudhaatru hui kai manuchh su saalan laashi so bahu peeno | 169 |","meaning_en":"as if a hungry man were drinking much curry with lassi. 169.","page":202,"meaning_status":"draft","note":"ਸਾਲਨ ਲਾਸਹਿ: read as 'curry and lassi'; uncertain."}]},{"type":"verse","number":[170],"number_text":"੧੭੦।","page":202,"lines":[{"gurmukhi":"ਜੁਧ ਰਕਤ੍ਰ ਬੀਜ ਕਰਿਯੋ ਧਰਨੀ ਪਰ ਸੋ ਸੁਰ ਦੇਖਤ ਸਾਰੇ।","roman":"Judh rakatr beej kariyo dharnee par so sur dekhat saare |","meaning_en":"Raktabij fought on the earth, while all the gods looked on;","page":202,"meaning_status":"draft"},{"gurmukhi":"ਜੇਤਕ ਸ੍ਰੌਨ ਕੀ ਬੂੰਦ ਗਿਰੈ ਉਠਿ ਤੇਤਕ ਰੂਪ ਅਨੇਕਹਿ ਧਾਰੇ।","roman":"Jetak sraun kee boond girai uthi tetak roop anekhi dhaare |","meaning_en":"as many drops of blood fell, so many forms arose.","page":202,"flags":[{"code":"0x71","reason":"subjoined letter typed after the vowel/nasal sign; put in Unicode order (same printed shape)"}],"meaning_status":"draft"},{"gurmukhi":"ਜੁਗਨਿ ਆਨਿ ਫਿਰੀ ਚਹੂੰ ਓਰ ਤੇ ਸੀਸ ਜਟਾ ਕਰਿ ਖਪਰ ਭਾਰੇ।","roman":"Jugni aani phiree chahoon or te sees jataa kari khapar bhaare |","meaning_en":"Yoginis came and moved about on all four sides, with matted hair on their heads and heavy begging bowls in their hands;","page":202,"meaning_status":"draft"},{"gurmukhi":"ਸ੍ਰੋਨਤ ਬੂੰਦ ਪਰੈ ਅਚਵੈ ਸਭ ਖਗ ਲੈ ਚੰਡ ਪ੍ਰਚੰਡ ਸੰਭਾਰੇ। ੧੭੦।","roman":"Sronat boond parai achvai sabh khag lai chand prachand sanbhaare | 170 |","meaning_en":"they drink up every drop of blood that falls, while fierce Chandi wields the sword. 170.","page":202,"meaning_status":"draft"}]},{"type":"verse","number":[171],"number_text":"੧੭੧।","page":202,"lines":[{"gurmukhi":"ਕਾਲੀ ਅਉ ਚੰਡਿ ਕੁਵੰਡ ਸੰਭਾਰ ਕੇ ਦੈਤ ਸੋ ਜੁਧ ਨਿਸੰਗ ਸਜਿਓ ਹੈ।","roman":"Kaalee au chandi kuvand sanbhaar ke dait so judh nisang sajio hai |","meaning_en":"Kali and Chandi, taking up the bow, waged war fearlessly with the demon.","page":202,"meaning_status":"draft"},{"gurmukhi":"ਮਾਰ ਮਹਾ ਰਨ ਮਧ ਭਈ ਪਹਰੇਕ ਲਉ ਸਾਰ ਸੋ ਸਾਰ ਬਜਿਓ ਹੈ।","roman":"Maar mahaa ran madh bhaee pahrek lau saar so saar bajio hai |","meaning_en":"Great slaughter took place on the field; for about a watch steel clashed against steel.","page":202,"meaning_status":"draft","note":"ਪਹਰੇਕ: about one pahar (three hours)."},{"gurmukhi":"ਸ੍ਰਉਨਤ ਬਿੰਦ ਗਿਰਿਓ ਧਰਨੀ ਪਰ ਇਉ ਅਸਿ ਸੋ ਅਰਿ ਸੀਸ ਭਜਿਓ ਹੈ।","roman":"Sraunat bind girio dharnee par iu asi so ari sees bhajio hai |","meaning_en":"Raktabij fell to the earth; thus by the sword the enemy's head was broken,","page":202,"meaning_status":"draft"},{"gurmukhi":"ਮਾਨੋ ਅਤੀਤ ਕਰਿਯੋ ਚਿਤ ਕੇ ਧਨਵੰਤ ਸਭੈ ਨਿਜ ਮਾਲ ਤਜਿਓ ਹੈ।੧੭੧।","roman":"Maano ateet kariyo chit ke dhanvant sabhai nij maal tajio hai | 171 |","meaning_en":"as if a rich man, having made his mind a renunciant's, had given up all his wealth. 171.","page":202,"meaning_status":"draft"}]},{"type":"heading","kind":"chhand","name":"ਸੋਰਠਾ","gurmukhi":"ਸੋਰਠਾ","roman":"Sorthaa","meaning_en":"Sortha.","page":202,"meaning_status":"draft"},{"type":"verse","number":[172],"number_text":"੧੭੨।","page":202,"lines":[{"gurmukhi":"ਚੰਡੀ ਦਇਓ ਬਿਦਾਰ ਸ੍ਰਉਨ ਪਾਨ ਕਾਲੀ ਕਰਿਓ।","roman":"Chandee daio bidaar sraun paan kaalee kario |","meaning_en":"Chandi tore him apart, and Kali drank the blood;","page":202,"meaning_status":"draft"},{"gurmukhi":"ਛਿਨ ਮੈ ਡਾਰਿਓ ਮਾਰ ਸ੍ਰਉਨਤ ਬਿੰਦ ਦਾਨਵ ਮਹਾ। ੧੭੨।","roman":"Chhin mai daario maar sraunat bind daanav mahaa | 172 |","meaning_en":"in an instant they slew the great demon Raktabij. 172.","page":202,"meaning_status":"draft"}]}],"ending":{"lines":[{"gurmukhi":"ਇਤਿ ਸ੍ਰੀ ਮਾਰਕੰਡੇ ਪੁਰਾਨੇ ਸ੍ਰੀ ਚੰਡੀ ਚਰਿਤ੍ਰ ਉਕਤਿ ਬਿਲਾਸ ਰਕਤ ਬੀਜ ਬਧਹਿ","roman":"Iti sree maarkande puraane sree chandee charitr ukti bilaas rakat beej badhhi","meaning_en":"Here ends, in the Markandey Puran, in Sri Chandi Charitr Ukti Bilaas, the chapter named the slaying of Raktabij,","page":202,"meaning_status":"draft"},{"gurmukhi":"ਨਾਮ ਪੰਚਮੋ ਧਿਆਇ ਸਮਾਪਤਮ ਸਤੁ ਸੁਭਮ ਸਤੁ। ੫।","roman":"Naam panchmo dhiaai samaaptam satu subham satu | 5 |","meaning_en":"the fifth chapter, complete. All is well; all is auspicious. 5.","page":202,"meaning_status":"draft"}],"page":202,"number":[5]}});
